// 510 questions. HOW TO EDIT:
//   correct = the right answer, wrong = exactly three wrong answers (the site shuffles them).
//   section: 3 Maths, 4 Technical basics, 5 Transmitters & receivers, 6 Lines & antennas,
//            7 Propagation, 8 Interference & EMC, 10 Safety, 11 Measurements.
//   image / imageAlt (optional): a picture in assets/questions/ shown above the options.
//   id prefixes: P = original fixed papers, X/M = hand-written, G = generated calculations, D = diagram questions.
//   Never reuse an id. To remove a question, add  retired: true  instead of deleting it.
window.QUESTIONS = [
  {"id":"P1-01","section":3,"question":"4.7 kΩ is equal to:","correct":"4 700 Ω","wrong":["470 Ω","47 000 Ω","0.0047 Ω"],"explain":"kilo = ×1 000, so 4.7 × 1 000 = 4 700 Ω."},
  {"id":"P1-02","section":3,"question":"22 000 pF is equal to:","correct":"0.022 µF","wrong":["0.22 µF","2.2 µF","22 µF"],"explain":"1 µF = 1 000 000 pF. Going pF → µF the number gets smaller: 22 000 ÷ 1 000 000 = 0.022 µF."},
  {"id":"P1-03","section":3,"question":"A transmitter's output drops from 100 W to 75 W. This is a reduction of:","correct":"25%","wrong":["75%","33%","0.25%"],"explain":"The drop is 25 W out of 100 W = 25/100 = 25%."},
  {"id":"P2-01","section":3,"question":"3.5 MHz is equal to:","correct":"3 500 kHz","wrong":["350 kHz","35 000 kHz","0.0035 kHz"],"explain":"1 MHz = 1 000 kHz, so 3.5 × 1 000 = 3 500 kHz."},
  {"id":"P2-02","section":3,"question":"0.47 µF is equal to:","correct":"470 000 pF","wrong":["4 700 pF","47 000 pF","470 pF"],"explain":"µF → pF multiply by 1 000 000: 0.47 × 1 000 000 = 470 000 pF."},
  {"id":"P2-03","section":3,"question":"Ohm's Law is E = I × R. Rearranged to find current, it becomes:","correct":"I = E ÷ R","wrong":["I = E × R","I = R ÷ E","I = E − R"],"explain":"Divide both sides by R: I = E / R."},
  {"id":"P3-01","section":3,"question":"145 000 kHz is equal to:","correct":"145 MHz","wrong":["1.45 MHz","14.5 MHz","1 450 MHz"],"explain":"Divide kHz by 1 000 to get MHz: 145 000 ÷ 1 000 = 145 MHz."},
  {"id":"P3-02","section":3,"question":"0.0022 H is equal to:","correct":"2.2 mH","wrong":["22 mH","2.2 µH","220 µH"],"explain":"milli = 0.001, so 0.0022 H = 2.2 mH."},
  {"id":"P3-03","section":3,"question":"A 12 V battery's voltage drops by 10%. The new voltage is:","correct":"10.8 V","wrong":["11.9 V","2 V","1.2 V"],"explain":"10% of 12 = 1.2 V. 12 − 1.2 = 10.8 V."},
  {"id":"X-01","section":3,"question":"1 500 mA is equal to:","correct":"1.5 A","wrong":["15 A","0.15 A","150 A"],"explain":"milli = ÷1 000: 1 500 ÷ 1 000 = 1.5 A."},
  {"id":"X-02","section":3,"question":"0.005 V is equal to:","correct":"5 mV","wrong":["50 mV","0.5 mV","5 µV"],"explain":"0.005 V × 1 000 = 5 mV."},
  {"id":"X-03","section":3,"question":"The fraction 3/4 expressed as a percentage is:","correct":"75%","wrong":["34%","0.75%","25%"],"explain":"3 ÷ 4 = 0.75, and 0.75 × 100 = 75%."},
  {"id":"G-001","section":3,"question":"2.2 kΩ is equal to:","correct":"2 200 Ω","wrong":["220 Ω","22 000 Ω","0.0022 Ω"],"explain":"kilo = ×1 000, so 2.2 × 1 000 = 2 200 Ω."},
  {"id":"G-002","section":3,"question":"68 kΩ is equal to:","correct":"68 000 Ω","wrong":["6 800 Ω","680 000 Ω","680 Ω"],"explain":"68 × 1 000 = 68 000 Ω."},
  {"id":"G-003","section":3,"question":"1.5 MΩ is equal to:","correct":"1 500 kΩ","wrong":["150 kΩ","15 000 kΩ","1.5 kΩ"],"explain":"mega → kilo is ×1 000: 1.5 × 1 000 = 1 500 kΩ."},
  {"id":"G-004","section":3,"question":"470 Ω is equal to:","correct":"0.47 kΩ","wrong":["4.7 kΩ","47 kΩ","0.047 kΩ"],"explain":"Ω → kΩ divide by 1 000: 470 ÷ 1 000 = 0.47 kΩ."},
  {"id":"G-005","section":3,"question":"100 pF is equal to:","correct":"0.0001 µF","wrong":["0.001 µF","0.01 µF","0.00001 µF"],"explain":"pF → µF divide by 1 000 000: 100 ÷ 1 000 000 = 0.0001 µF."},
  {"id":"G-006","section":3,"question":"0.1 µF is equal to:","correct":"100 000 pF","wrong":["10 000 pF","1 000 000 pF","1 000 pF"],"explain":"µF → pF multiply by 1 000 000: 0.1 × 1 000 000 = 100 000 pF."},
  {"id":"G-007","section":3,"question":"4 700 pF is equal to:","correct":"0.0047 µF","wrong":["0.047 µF","0.00047 µF","4.7 µF"],"explain":"4 700 ÷ 1 000 000 = 0.0047 µF."},
  {"id":"G-008","section":3,"question":"0.001 µF is equal to:","correct":"1 000 pF","wrong":["100 pF","10 000 pF","10 pF"],"explain":"0.001 × 1 000 000 = 1 000 pF."},
  {"id":"G-009","section":3,"question":"7.1 MHz is equal to:","correct":"7 100 kHz","wrong":["710 kHz","71 000 kHz","0.0071 kHz"],"explain":"MHz → kHz multiply by 1 000: 7.1 × 1 000 = 7 100 kHz."},
  {"id":"G-010","section":3,"question":"14 250 kHz is equal to:","correct":"14.25 MHz","wrong":["142.5 MHz","1.425 MHz","1 425 MHz"],"explain":"kHz → MHz divide by 1 000: 14 250 ÷ 1 000 = 14.25 MHz."},
  {"id":"G-011","section":3,"question":"438.5 MHz is equal to:","correct":"438 500 kHz","wrong":["43 850 kHz","4 385 000 kHz","0.4385 kHz"],"explain":"438.5 × 1 000 = 438 500 kHz."},
  {"id":"G-012","section":3,"question":"250 mA is equal to:","correct":"0.25 A","wrong":["2.5 A","25 A","0.025 A"],"explain":"mA → A divide by 1 000: 250 ÷ 1 000 = 0.25 A."},
  {"id":"G-013","section":3,"question":"0.05 A is equal to:","correct":"50 mA","wrong":["5 mA","500 mA","0.5 mA"],"explain":"A → mA multiply by 1 000: 0.05 × 1 000 = 50 mA."},
  {"id":"G-014","section":3,"question":"2 500 W is equal to:","correct":"2.5 kW","wrong":["25 kW","0.25 kW","250 kW"],"explain":"W → kW divide by 1 000: 2 500 ÷ 1 000 = 2.5 kW."},
  {"id":"G-015","section":3,"question":"0.000 01 F is equal to:","correct":"10 µF","wrong":["1 µF","100 µF","0.1 µF"],"explain":"F → µF multiply by 1 000 000: 0.00001 × 1 000 000 = 10 µF."},
  {"id":"G-016","section":3,"question":"15 µH is equal to:","correct":"0.015 mH","wrong":["0.15 mH","1.5 mH","0.0015 mH"],"explain":"µH → mH divide by 1 000: 15 ÷ 1 000 = 0.015 mH."},
  {"id":"G-017","section":3,"question":"A 400 W linear amplifier is run at 25% of its rated output. The output power is:","correct":"100 W","wrong":["25 W","160 W","375 W"],"explain":"25% of 400 = 0.25 × 400 = 100 W."},
  {"id":"G-018","section":3,"question":"A 50 W transmitter's output rises by 20%. The new output is:","correct":"60 W","wrong":["70 W","52 W","40 W"],"explain":"20% of 50 W = 10 W. 50 + 10 = 60 W."},
  {"id":"P1-04","section":4,"question":"The nominal mains supply voltage and frequency in Australia is:","correct":"230 V, 50 Hz","wrong":["240 V, 60 Hz","110 V, 60 Hz","230 V, 60 Hz"],"explain":"Australian mains is 230 V AC at 50 Hz (MEN system)."},
  {"id":"P1-05","section":4,"question":"In Australian mains wiring, the Active conductor is coloured:","correct":"Brown","wrong":["Blue","Green/yellow","Black"],"explain":"Active = brown, Neutral = blue, Earth = green/yellow."},
  {"id":"P1-06","section":4,"question":"In mains-operated equipment, the fuse and on/off switch should be placed in the:","correct":"Active lead","wrong":["Neutral lead","Earth lead","Neutral and earth leads"],"explain":"Fuses and switches go in the Active so that, when they open, the equipment is disconnected from the live supply."},
  {"id":"P1-07","section":4,"question":"The main reason for the Earth connection on mains-operated equipment is to:","correct":"Provide a low-resistance path for fault current so the fuse or protection operates and the case cannot become live","wrong":["Reduce hum in the audio","Improve the radio's receive sensitivity","Carry the normal operating current back to the switchboard"],"explain":"If a live wire touches a metal case, the earth carries a large fault current that blows the fuse/trips protection, preventing electric shock."},
  {"id":"P1-08","section":4,"question":"A bridge rectifier uses:","correct":"Four diodes","wrong":["One diode","Two diodes and a centre-tapped transformer","Three diodes"],"explain":"A bridge rectifier uses four diodes and does not need a centre-tapped transformer."},
  {"id":"P1-09","section":4,"question":"A full-wave rectifier is fed from the 50 Hz mains. The ripple frequency at its output is:","correct":"100 Hz","wrong":["50 Hz","25 Hz","200 Hz"],"explain":"Full-wave and bridge rectifiers use both half cycles, so ripple is twice the input frequency: 2 × 50 = 100 Hz."},
  {"id":"P1-10","section":4,"question":"The peak inverse voltage (PIV) rating of a rectifier diode is:","correct":"The maximum reverse voltage the diode can withstand without breaking down","wrong":["The forward voltage drop when the diode conducts","The average DC output voltage of the power supply","The voltage at which the diode starts to conduct forwards"],"explain":"Exceeding the PIV causes reverse (avalanche) breakdown, which can destroy the diode."},
  {"id":"P1-11","section":4,"question":"A resistor is coded brown, black, red, gold. Its value is:","correct":"1 kΩ ±5%","wrong":["102 Ω ±5%","10 kΩ ±5%","1 kΩ ±10%"],"explain":"Brown = 1, black = 0, red = ×100 → 10 × 100 = 1 000 Ω. Gold = ±5%."},
  {"id":"P1-12","section":4,"question":"Three 330 Ω resistors are connected in series. The total resistance is:","correct":"990 Ω","wrong":["110 Ω","330 Ω","660 Ω"],"explain":"In series resistances add: 330 + 330 + 330 = 990 Ω."},
  {"id":"P1-13","section":4,"question":"A 60 Ω resistor is connected across a 12 V supply. The current is:","correct":"0.2 A","wrong":["5 A","720 mA","72 A"],"explain":"I = E / R = 12 / 60 = 0.2 A (200 mA)."},
  {"id":"P1-14","section":4,"question":"A current of 2 A flows through a 10 Ω resistor. The power dissipated is:","correct":"40 W","wrong":["20 W","5 W","200 W"],"explain":"P = I²R = 2² × 10 = 4 × 10 = 40 W."},
  {"id":"P1-15","section":4,"question":"A capacitor consists of:","correct":"Two conducting surfaces separated by an insulator","wrong":["A coil of wire wound on a former","Two semiconductor layers forming a junction","A single plate connected to earth"],"explain":"Two conductive plates separated by an insulator (the dielectric)."},
  {"id":"P1-16","section":4,"question":"Two 10 µF capacitors are connected in series. The total capacitance is:","correct":"5 µF","wrong":["20 µF","10 µF","100 µF"],"explain":"Capacitors in series use the reciprocal rule. Two equal values in series = half of one: 10 ÷ 2 = 5 µF."},
  {"id":"P1-17","section":4,"question":"A sine wave has a peak value of 100 V. Its RMS value is approximately:","correct":"70.7 V","wrong":["141 V","50 V","200 V"],"explain":"RMS = 0.707 × peak = 0.707 × 100 = 70.7 V."},
  {"id":"P2-04","section":4,"question":"In a correctly wired Australian MEN installation, the voltage between Neutral and Earth is approximately:","correct":"0 V","wrong":["230 V","115 V","50 V"],"explain":"Neutral is bonded to earth at the switchboard, so N–E is near 0 V (more than ~2 V suggests a fault)."},
  {"id":"P2-05","section":4,"question":"The Earth conductor in Australian mains wiring is coloured:","correct":"Green/yellow","wrong":["Brown","Blue","Red"],"explain":"Earth = green/yellow, Active = brown, Neutral = blue."},
  {"id":"P2-06","section":4,"question":"A half-wave rectifier is fed from the 50 Hz mains. The ripple frequency at its output is:","correct":"50 Hz","wrong":["100 Hz","25 Hz","200 Hz"],"explain":"A half-wave rectifier conducts on one half cycle only, so ripple equals the input frequency: 50 Hz."},
  {"id":"P2-07","section":4,"question":"A FET amplifier in which the source terminal is common to both input and output is called a:","correct":"Common-source amplifier","wrong":["Common-emitter amplifier","Common-drain amplifier","Common-gate amplifier"],"explain":"For a FET, the source being common gives the common-source configuration (the FET equivalent of common emitter)."},
  {"id":"P2-08","section":4,"question":"A bleeder resistor is connected across the filter capacitor of a power supply to:","correct":"Discharge the capacitor after the supply is switched off","wrong":["Increase the output voltage","Act as a fuse","Increase the ripple"],"explain":"Large or high-voltage capacitors can hold a dangerous charge after switch-off. A bleeder resistor drains it away."},
  {"id":"P2-09","section":4,"question":"The typical forward voltage drop across a silicon diode is about:","correct":"0.6 V","wrong":["0.2 V","1.5 V","6 V"],"explain":"Silicon ≈ 0.6 V (often quoted 0.6–0.7 V). Germanium ≈ 0.2 V."},
  {"id":"P2-10","section":4,"question":"A resistor is coded yellow, violet, orange. Its value is:","correct":"47 kΩ","wrong":["4.7 kΩ","470 Ω","470 kΩ"],"explain":"Yellow = 4, violet = 7, orange = ×1 000 → 47 000 Ω = 47 kΩ. No 4th band = ±20%."},
  {"id":"P2-11","section":4,"question":"Four 100 Ω resistors are connected in parallel. The total resistance is:","correct":"25 Ω","wrong":["400 Ω","100 Ω","50 Ω"],"explain":"Equal values in parallel: divide one value by the number of resistors: 100 ÷ 4 = 25 Ω."},
  {"id":"P2-12","section":4,"question":"Two 20 Ω resistors in parallel are connected in series with another 20 Ω resistor. The total resistance is:","correct":"30 Ω","wrong":["60 Ω","40 Ω","13.3 Ω"],"explain":"The parallel pair = 20 ÷ 2 = 10 Ω. Add the series resistor: 10 + 20 = 30 Ω."},
  {"id":"P2-13","section":4,"question":"A 5 V supply is connected across a 1 kΩ resistor. The current is:","correct":"5 mA","wrong":["5 A","0.5 mA","200 mA"],"explain":"I = E / R = 5 / 1 000 = 0.005 A = 5 mA."},
  {"id":"P2-14","section":4,"question":"A transceiver draws 20 A from a 13.8 V supply. The power consumed is:","correct":"276 W","wrong":["1.45 W","33.8 W","27.6 W"],"explain":"P = E × I = 13.8 × 20 = 276 W."},
  {"id":"P2-15","section":4,"question":"The unit of inductance is the:","correct":"Henry","wrong":["Farad","Ohm","Hertz"],"explain":"Inductance is measured in henrys (H). Capacitance is in farads."},
  {"id":"P2-16","section":4,"question":"Which change will INCREASE the inductance of a coil?","correct":"Increasing the number of turns","wrong":["Reducing the coil diameter","Spacing the turns further apart","Reducing the number of turns"],"explain":"Inductance increases with more turns, larger diameter and closer spacing between turns."},
  {"id":"P2-17","section":4,"question":"The period of one cycle of the 50 Hz mains is:","correct":"20 ms","wrong":["50 ms","2 ms","0.5 s"],"explain":"T = 1 / f = 1 / 50 = 0.02 s = 20 ms."},
  {"id":"P3-04","section":4,"question":"An item of mains-operated equipment has only a two-pin plug (no earth pin). This usually means it is:","correct":"Double insulated","wrong":["Faulty and unsafe","Designed for 110 V","Not approved for use"],"explain":"Double-insulated equipment does not need an earth connection and has no earth pin."},
  {"id":"P3-05","section":4,"question":"In the symbol for a bipolar transistor, the arrow on the emitter points inwards towards the base. The transistor is a:","correct":"PNP transistor","wrong":["NPN transistor","Field effect transistor","Zener diode"],"explain":"Memory jogger: PNP = 'Pointing iN Proudly'. NPN = 'Not Pointing iN'."},
  {"id":"P3-06","section":4,"question":"An electrolytic capacitor is described as 'polarised'. This means it:","correct":"Must be connected with the correct polarity or it may fail, sometimes violently","wrong":["Can be connected either way round","Only works on AC","Has no voltage rating"],"explain":"Polarised capacitors have + and − terminals. Reverse connection can damage or burst them."},
  {"id":"P3-07","section":4,"question":"Which change will INCREASE the capacitance of a capacitor?","correct":"Moving the plates closer together","wrong":["Moving the plates further apart","Reducing the plate area","Removing the dielectric material"],"explain":"Capacitance increases with larger plate area, smaller separation and a better dielectric."},
  {"id":"P3-08","section":4,"question":"Three 30 pF capacitors are connected in parallel. The total capacitance is:","correct":"90 pF","wrong":["10 pF","30 pF","60 pF"],"explain":"Capacitors in parallel add: 30 + 30 + 30 = 90 pF."},
  {"id":"P3-09","section":4,"question":"Two 6 mH inductors are connected in parallel (no mutual coupling). The total inductance is:","correct":"3 mH","wrong":["12 mH","6 mH","36 mH"],"explain":"Inductors follow the same rules as resistors. Two equal values in parallel = half: 6 ÷ 2 = 3 mH."},
  {"id":"P3-10","section":4,"question":"'Reactance' describes:","correct":"The opposition to alternating current in a purely inductive or capacitive circuit","wrong":["The opposition to direct current in a resistor","The total power in a circuit","The ratio of turns in a transformer"],"explain":"Reactance (X) is the opposition from inductance or capacitance. Impedance (Z) is the total opposition in an AC circuit."},
  {"id":"P3-11","section":4,"question":"At resonance in a tuned circuit:","correct":"XL equals XC and the impedance is purely resistive","wrong":["XL is twice XC","The circuit has no resistance at all","The impedance is purely capacitive"],"explain":"At resonance inductive and capacitive reactances are equal and cancel, leaving only resistance."},
  {"id":"P3-12","section":4,"question":"At resonance, a SERIES tuned circuit has:","correct":"Minimum impedance","wrong":["Maximum impedance","Infinite impedance","Purely inductive impedance"],"explain":"Series resonant = minimum impedance (maximum current). Parallel resonant = maximum impedance."},
  {"id":"P3-13","section":4,"question":"The Q factor of a tuned circuit is an indicator of:","correct":"The amount of losses in the circuit. Low losses give high Q and a narrow bandwidth","wrong":["The circuit's operating voltage","The number of components","The resonant frequency only"],"explain":"Fewer losses means higher Q and sharper (narrower) response."},
  {"id":"P3-14","section":4,"question":"A transformer has a turns ratio of 10:1 (primary:secondary). With 230 V applied to the primary, the secondary voltage is:","correct":"23 V","wrong":["2 300 V","230 V","10 V"],"explain":"The voltage ratio equals the turns ratio: 230 ÷ 10 = 23 V. The current ratio is the inverse."},
  {"id":"P3-15","section":4,"question":"Transformer cores are made from laminations or ferrite in order to:","correct":"Reduce eddy current losses","wrong":["Increase eddy currents","Make the transformer lighter only","Increase the turns ratio"],"explain":"Eddy currents circulate in a solid core and cause heating. Laminations or ferrite break them up."},
  {"id":"P3-16","section":4,"question":"A Zener diode is commonly used as a:","correct":"Voltage regulator","wrong":["Variable capacitor","Mixer","Power amplifier"],"explain":"A reverse-biased Zener holds a stable voltage across the load."},
  {"id":"P3-17","section":4,"question":"A varactor (varicap) diode behaves as a:","correct":"Voltage-variable capacitor","wrong":["Voltage regulator","Light source","Fixed resistor"],"explain":"Its capacitance changes with reverse bias voltage, which is useful for electronic tuning and FM modulators."},
  {"id":"X-04","section":4,"question":"Voltage (EMF, potential difference) is best described as:","correct":"The electrical 'pressure' that pushes current around a circuit","wrong":["The rate of flow of electric charge","The opposition to current flow","The power used by a circuit"],"explain":"Voltage is the electrical pressure. Current is the flow, and resistance opposes it."},
  {"id":"X-05","section":4,"question":"Electrical current is:","correct":"The flow of electric charge through a conductor, measured in amperes","wrong":["The pressure that pushes electrons, measured in volts","The opposition to flow, measured in ohms","Stored energy in a capacitor, measured in farads"],"explain":"Current is the rate of flow of charge, measured in amps (A)."},
  {"id":"X-06","section":4,"question":"Faraday's law of induction states that:","correct":"When relative motion exists between a conductor and a magnetic field, a voltage is induced in the conductor","wrong":["Current is proportional to voltage divided by resistance","The sum of currents into a junction equals the sum flowing out","Capacitance depends on plate area"],"explain":"Relative motion between a conductor and a magnetic field induces a voltage. It is the principle behind transformers."},
  {"id":"X-07","section":4,"question":"A transformer steps the voltage UP by a ratio of 1:5. Ignoring losses, the secondary current compared with the primary current is:","correct":"One fifth","wrong":["Five times greater","The same","Twenty-five times greater"],"explain":"Power in = power out, so if voltage goes up 5 times, current goes down to one fifth."},
  {"id":"X-08","section":4,"question":"An inductor stores energy in its:","correct":"Magnetic field","wrong":["Electric field between plates","Dielectric","Semiconductor junction"],"explain":"Inductors store energy in a magnetic field. Capacitors store it in an electric field."},
  {"id":"X-09","section":4,"question":"Impedance is:","correct":"The total opposition to current flow in an AC circuit","wrong":["The opposition of a pure resistor to DC only","The frequency of an AC signal","The power factor of a circuit"],"explain":"Impedance (Z) combines resistance and reactance and is measured in ohms."},
  {"id":"X-10","section":4,"question":"One complete cycle of an AC waveform is equal to:","correct":"360 degrees","wrong":["180 degrees","90 degrees","720 degrees"],"explain":"A full cycle is 360°. Each half cycle is 180°."},
  {"id":"X-11","section":4,"question":"At resonance, a PARALLEL tuned circuit has:","correct":"Maximum impedance","wrong":["Minimum impedance","Zero impedance","Purely capacitive impedance"],"explain":"Parallel resonant = maximum impedance. Series resonant = minimum."},
  {"id":"X-12","section":4,"question":"The typical forward voltage drop across a germanium diode is about:","correct":"0.2 V","wrong":["0.6 V","1.2 V","5 V"],"explain":"Germanium ≈ 0.2 V. Silicon ≈ 0.6 V."},
  {"id":"X-13","section":4,"question":"A resistor is coded red, red, brown, gold. Its value is:","correct":"220 Ω ±5%","wrong":["22 Ω ±5%","2.2 kΩ ±5%","221 Ω ±5%"],"explain":"Red 2, red 2, brown ×10 → 220 Ω. Gold = ±5%."},
  {"id":"X-14","section":4,"question":"Three 9 mH inductors are connected in series (no mutual coupling). The total inductance is:","correct":"27 mH","wrong":["3 mH","9 mH","18 mH"],"explain":"Inductors in series add: 9 + 9 + 9 = 27 mH."},
  {"id":"G-019","section":4,"question":"A 24 V supply is connected across a 120 Ω resistor. The current is:","correct":"200 mA","wrong":["2 A","20 mA","5 A"],"explain":"I = E / R = 24 / 120 = 0.2 A."},
  {"id":"G-020","section":4,"question":"A 9 V supply is connected across a 450 Ω resistor. The current is:","correct":"20 mA","wrong":["200 mA","2 mA","50 A"],"explain":"I = E / R = 9 / 450 = 0.02 A."},
  {"id":"G-021","section":4,"question":"A 13.8 V supply is connected across a 2.3 Ω resistor. The current is:","correct":"6 A","wrong":["60 A","600 mA","166.7 mA"],"explain":"I = E / R = 13.8 / 2.3 = 6 A."},
  {"id":"G-022","section":4,"question":"A 48 V supply is connected across a 16 Ω resistor. The current is:","correct":"3 A","wrong":["30 A","300 mA","333.3 mA"],"explain":"I = E / R = 48 / 16 = 3 A."},
  {"id":"G-023","section":4,"question":"A 6 V supply is connected across a 1.2 kΩ resistor. The current is:","correct":"5 mA","wrong":["50 mA","0.5 mA","200 A"],"explain":"I = E / R = 6 / 1 200 = 0.005 A."},
  {"id":"G-024","section":4,"question":"A 230 V supply is connected across a 46 Ω resistor. The current is:","correct":"5 A","wrong":["50 A","500 mA","200 mA"],"explain":"I = E / R = 230 / 46 = 5 A."},
  {"id":"G-025","section":4,"question":"A current of 500 mA flows through a 100 Ω resistor. The voltage across it is:","correct":"50 V","wrong":["500 V","5 V","200 V"],"explain":"E = I × R = 0.5 × 100 = 50 V."},
  {"id":"G-026","section":4,"question":"A current of 2 A flows through a 47 Ω resistor. The voltage across it is:","correct":"94 V","wrong":["940 V","9.4 V","23.5 V"],"explain":"E = I × R = 2 × 47 = 94 V."},
  {"id":"G-027","section":4,"question":"A current of 20 mA flows through a 1 kΩ resistor. The voltage across it is:","correct":"20 V","wrong":["200 V","2 V","50 000 V"],"explain":"E = I × R = 0.02 × 1 000 = 20 V."},
  {"id":"G-028","section":4,"question":"A current of 3 A flows through a 4.6 Ω resistor. The voltage across it is:","correct":"13.8 V","wrong":["138 V","1.38 V","1.533 V"],"explain":"E = I × R = 3 × 4.6 = 13.8 V."},
  {"id":"G-029","section":4,"question":"A current of 150 mA flows through a 220 Ω resistor. The voltage across it is:","correct":"33 V","wrong":["330 V","3.3 V","1 467 V"],"explain":"E = I × R = 0.15 × 220 = 33 V."},
  {"id":"G-030","section":4,"question":"12 V across a resistor causes 500 mA to flow. The resistance is:","correct":"24 Ω","wrong":["6 Ω","240 Ω","2.4 Ω"],"explain":"R = E / I = 12 / 0.5 = 24 Ω."},
  {"id":"G-031","section":4,"question":"230 V across a resistor causes 2 A to flow. The resistance is:","correct":"115 Ω","wrong":["460 Ω","1 150 Ω","11.5 Ω"],"explain":"R = E / I = 230 / 2 = 115 Ω."},
  {"id":"G-032","section":4,"question":"5 V across a resistor causes 25 mA to flow. The resistance is:","correct":"200 Ω","wrong":["0.125 Ω","2 000 Ω","20 Ω"],"explain":"R = E / I = 5 / 0.025 = 200 Ω."},
  {"id":"G-033","section":4,"question":"13.8 V across a resistor causes 600 mA to flow. The resistance is:","correct":"23 Ω","wrong":["8.28 Ω","230 Ω","2.3 Ω"],"explain":"R = E / I = 13.8 / 0.6 = 23 Ω."},
  {"id":"G-034","section":4,"question":"100 V across a resistor causes 4 A to flow. The resistance is:","correct":"25 Ω","wrong":["400 Ω","250 Ω","2.5 Ω"],"explain":"R = E / I = 100 / 4 = 25 Ω."},
  {"id":"G-035","section":4,"question":"A device draws 3 A from a 12 V supply. The power consumed is:","correct":"36 W","wrong":["4 W","72 W","18 W"],"explain":"P = E × I = 12 × 3 = 36 W."},
  {"id":"G-036","section":4,"question":"A device draws 0.5 A from a 230 V supply. The power consumed is:","correct":"115 W","wrong":["460 W","230 W","57.5 W"],"explain":"P = E × I = 230 × 0.5 = 115 W."},
  {"id":"G-037","section":4,"question":"A device draws 10 A from a 13.8 V supply. The power consumed is:","correct":"138 W","wrong":["1.38 W","276 W","69 W"],"explain":"P = E × I = 13.8 × 10 = 138 W."},
  {"id":"G-038","section":4,"question":"A device draws 2 A from a 50 V supply. The power consumed is:","correct":"100 W","wrong":["25 W","200 W","50 W"],"explain":"P = E × I = 50 × 2 = 100 W."},
  {"id":"G-039","section":4,"question":"10 V is applied across a 50 Ω resistor. The power dissipated is:","correct":"2 W","wrong":["0.2 W","500 W","4 W"],"explain":"P = E² / R = 10² / 50 = 100 / 50 = 2 W."},
  {"id":"G-040","section":4,"question":"20 V is applied across a 100 Ω resistor. The power dissipated is:","correct":"4 W","wrong":["0.2 W","2 000 W","8 W"],"explain":"P = E² / R = 20² / 100 = 400 / 100 = 4 W."},
  {"id":"G-041","section":4,"question":"12 V is applied across a 8 Ω resistor. The power dissipated is:","correct":"18 W","wrong":["1.5 W","96 W","36 W"],"explain":"P = E² / R = 12² / 8 = 144 / 8 = 18 W."},
  {"id":"G-042","section":4,"question":"100 V is applied across a 50 Ω resistor. The power dissipated is:","correct":"200 W","wrong":["2 W","5 000 W","400 W"],"explain":"P = E² / R = 100² / 50 = 10 000 / 50 = 200 W."},
  {"id":"G-043","section":4,"question":"A current of 3 A flows through a 5 Ω resistor. The power dissipated is:","correct":"45 W","wrong":["15 W","90 W","450 W"],"explain":"P = I²R = 3² × 5 = 45 W."},
  {"id":"G-044","section":4,"question":"A current of 0.5 A flows through a 100 Ω resistor. The power dissipated is:","correct":"25 W","wrong":["50 W","250 W","2.5 W"],"explain":"P = I²R = 0.5² × 100 = 25 W."},
  {"id":"G-045","section":4,"question":"A current of 10 A flows through a 0.1 Ω resistor. The power dissipated is:","correct":"10 W","wrong":["1 W","20 W","100 W"],"explain":"P = I²R = 10² × 0.1 = 10 W."},
  {"id":"G-046","section":4,"question":"Two 470 Ω resistors are connected in series. The total resistance is:","correct":"940 Ω","wrong":["235 Ω","470 Ω","1 880 Ω"],"explain":"Resistors in series add. 2 × 470 = 940 Ω."},
  {"id":"G-047","section":4,"question":"Three 1 200 Ω resistors are connected in parallel. The total resistance is:","correct":"400 Ω","wrong":["3 600 Ω","1 200 Ω","2 400 Ω"],"explain":"Equal values in parallel: divide one value by the number of components. 1 200 ÷ 3 = 400 Ω."},
  {"id":"G-048","section":4,"question":"Five 50 Ω resistors are connected in parallel. The total resistance is:","correct":"10 Ω","wrong":["250 Ω","50 Ω","200 Ω"],"explain":"Equal values in parallel: divide one value by the number of components. 50 ÷ 5 = 10 Ω."},
  {"id":"G-049","section":4,"question":"Four 22 Ω resistors are connected in series. The total resistance is:","correct":"88 Ω","wrong":["5.5 Ω","22 Ω","66 Ω"],"explain":"Resistors in series add. 4 × 22 = 88 Ω."},
  {"id":"G-050","section":4,"question":"Three 33 µF capacitors are connected in series. The total capacitance is:","correct":"11 µF","wrong":["99 µF","33 µF","66 µF"],"explain":"Capacitors in series follow the reciprocal rule, so equal values divide by the number of capacitors. 33 ÷ 3 = 11 µF."},
  {"id":"G-051","section":4,"question":"Four 25 pF capacitors are connected in parallel. The total capacitance is:","correct":"100 pF","wrong":["6.25 pF","25 pF","75 pF"],"explain":"Capacitors in parallel add. 4 × 25 = 100 pF."},
  {"id":"G-052","section":4,"question":"Two 470 µF capacitors are connected in parallel. The total capacitance is:","correct":"940 µF","wrong":["235 µF","470 µF","1 880 µF"],"explain":"Capacitors in parallel add. 2 × 470 = 940 µF."},
  {"id":"G-053","section":4,"question":"Four 100 nF capacitors are connected in series. The total capacitance is:","correct":"25 nF","wrong":["400 nF","100 nF","300 nF"],"explain":"Capacitors in series follow the reciprocal rule, so equal values divide by the number of capacitors. 100 ÷ 4 = 25 nF."},
  {"id":"G-054","section":4,"question":"Three 12 µH inductors are connected in series (no mutual coupling). The total inductance is:","correct":"36 µH","wrong":["4 µH","12 µH","24 µH"],"explain":"Inductors in series add. 3 × 12 = 36 µH."},
  {"id":"G-055","section":4,"question":"Four 20 mH inductors are connected in parallel (no mutual coupling). The total inductance is:","correct":"5 mH","wrong":["80 mH","20 mH","60 mH"],"explain":"Equal values in parallel: divide one value by the number of components. 20 ÷ 4 = 5 mH."},
  {"id":"G-056","section":4,"question":"Two 50 µH inductors are connected in parallel (no mutual coupling). The total inductance is:","correct":"25 µH","wrong":["100 µH","50 µH","12.5 µH"],"explain":"Equal values in parallel: divide one value by the number of components. 50 ÷ 2 = 25 µH."},
  {"id":"G-057","section":4,"question":"Two 100 Ω resistors in parallel are connected in series with two more 100 Ω resistors in parallel. The total resistance is:","correct":"100 Ω","wrong":["400 Ω","50 Ω","200 Ω"],"explain":"Each parallel pair = 100 ÷ 2 = 50 Ω. Two 50 Ω sections in series = 100 Ω."},
  {"id":"G-058","section":4,"question":"Three 30 Ω resistors in parallel are connected in series with a 30 Ω resistor. The total resistance is:","correct":"40 Ω","wrong":["120 Ω","10 Ω","60 Ω"],"explain":"Parallel group = 30 ÷ 3 = 10 Ω. Add the series 30 Ω: 10 + 30 = 40 Ω."},
  {"id":"G-059","section":4,"question":"Two 10 µF capacitors in series are connected in parallel with a 10 µF capacitor. The total capacitance is:","correct":"15 µF","wrong":["30 µF","5 µF","3.3 µF"],"explain":"Series pair = 10 ÷ 2 = 5 µF. Adding the parallel capacitor: 5 + 10 = 15 µF."},
  {"id":"G-060","section":4,"question":"Two 8 mH inductors in parallel are connected in series with an 8 mH inductor (no mutual coupling). The total inductance is:","correct":"12 mH","wrong":["24 mH","4 mH","2.7 mH"],"explain":"Parallel pair = 8 ÷ 2 = 4 mH. Add the series 8 mH: 4 + 8 = 12 mH."},
  {"id":"G-061","section":4,"question":"A resistor is coded brown, green, red, gold. Its value is:","correct":"1.5 kΩ ±5%","wrong":["15 kΩ ±5%","150 Ω ±5%","1.5 kΩ ±10%"],"explain":"brown = 1, green = 5, red = ×100 → 1 500 Ω = 1.5 kΩ. Gold = ±5%."},
  {"id":"G-062","section":4,"question":"A resistor is coded orange, orange, brown, gold. Its value is:","correct":"330 Ω ±5%","wrong":["3.3 kΩ ±5%","33 Ω ±5%","330 Ω ±10%"],"explain":"orange = 3, orange = 3, brown = ×10 → 330 Ω = 330 Ω. Gold = ±5%."},
  {"id":"G-063","section":4,"question":"A resistor is coded green, blue, orange, silver. Its value is:","correct":"56 kΩ ±10%","wrong":["560 kΩ ±10%","5.6 kΩ ±10%","56 kΩ ±5%"],"explain":"green = 5, blue = 6, orange = ×1 000 → 56 000 Ω = 56 kΩ. Silver = ±10%."},
  {"id":"G-064","section":4,"question":"A resistor is coded red, violet, yellow, gold. Its value is:","correct":"270 kΩ ±5%","wrong":["2.7 MΩ ±5%","27 kΩ ±5%","270 kΩ ±10%"],"explain":"red = 2, violet = 7, yellow = ×10 000 → 270 000 Ω = 270 kΩ. Gold = ±5%."},
  {"id":"G-065","section":4,"question":"A resistor is coded grey, red, black, gold. Its value is:","correct":"82 Ω ±5%","wrong":["820 Ω ±5%","8.2 Ω ±5%","82 Ω ±10%"],"explain":"grey = 8, red = 2, black = ×1 → 82 Ω = 82 Ω. Gold = ±5%."},
  {"id":"G-066","section":4,"question":"A resistor is coded brown, black, green, silver. Its value is:","correct":"1 MΩ ±10%","wrong":["10 MΩ ±10%","100 kΩ ±10%","1 MΩ ±5%"],"explain":"brown = 1, black = 0, green = ×100 000 → 1 000 000 Ω = 1 MΩ. Silver = ±10%."},
  {"id":"G-067","section":4,"question":"A resistor is coded blue, grey, red, gold. Its value is:","correct":"6.8 kΩ ±5%","wrong":["68 kΩ ±5%","680 Ω ±5%","6.8 kΩ ±10%"],"explain":"blue = 6, grey = 8, red = ×100 → 6 800 Ω = 6.8 kΩ. Gold = ±5%."},
  {"id":"G-068","section":4,"question":"A resistor is coded orange, white, orange (no fourth band). Its value is:","correct":"39 kΩ ±20%","wrong":["390 kΩ ±20%","3.9 kΩ ±20%","39 kΩ ±5%"],"explain":"orange = 3, white = 9, orange = ×1 000 → 39 000 Ω = 39 kΩ. No tolerance band = ±20%."},
  {"id":"G-069","section":4,"question":"A sine wave has a peak value of 10 V. Its RMS value is approximately:","correct":"7.07 V","wrong":["14.14 V","5 V","20 V"],"explain":"RMS = 0.707 × peak = 0.707 × 10 ≈ 7.07 V."},
  {"id":"G-070","section":4,"question":"A sine wave has a peak value of 340 V. Its RMS value is approximately:","correct":"240.4 V","wrong":["480.8 V","170 V","680 V"],"explain":"RMS = 0.707 × peak = 0.707 × 340 ≈ 240.4 V."},
  {"id":"G-071","section":4,"question":"A sine wave has a peak value of 20 V. Its RMS value is approximately:","correct":"14.14 V","wrong":["28.28 V","10 V","40 V"],"explain":"RMS = 0.707 × peak = 0.707 × 20 ≈ 14.14 V."},
  {"id":"G-072","section":4,"question":"The period of one cycle of a 1 kHz signal is:","correct":"1 ms","wrong":["10 ms","100 µs","1 000 ms"],"explain":"T = 1 / f = 1 / 1 000 = 1 ms."},
  {"id":"G-073","section":4,"question":"The period of one cycle of a 100 Hz signal is:","correct":"10 ms","wrong":["100 ms","1 ms","10 000 ms"],"explain":"T = 1 / f = 1 / 100 = 10 ms."},
  {"id":"G-074","section":4,"question":"The period of one cycle of a 10 kHz signal is:","correct":"100 µs","wrong":["1 ms","10 µs","100 ms"],"explain":"T = 1 / f = 1 / 10 000 = 100 µs."},
  {"id":"G-075","section":4,"question":"A waveform has a period of 2 ms. Its frequency is:","correct":"500 Hz","wrong":["5 kHz","50 Hz","500 kHz"],"explain":"f = 1 / T = 1 / 0.002 s = 500 Hz."},
  {"id":"G-076","section":4,"question":"A waveform has a period of 100 µs. Its frequency is:","correct":"10 kHz","wrong":["100 kHz","1 kHz","10 000 kHz"],"explain":"f = 1 / T = 1 / 0.0001 s = 10 kHz."},
  {"id":"G-077","section":4,"question":"A transformer has 1 000 primary turns and 50 secondary turns. With 230 V on the primary, the secondary voltage is:","correct":"11.5 V","wrong":["4 600 V","23 V","115 V"],"explain":"Turns ratio 1 000:50 = 20:1. 230 ÷ 20 = 11.5 V."},
  {"id":"G-078","section":4,"question":"A transformer steps 230 V down to 23 V. If the secondary supplies 2 A, the primary current (ignoring losses) is:","correct":"0.2 A","wrong":["20 A","2 A","0.02 A"],"explain":"Power in = power out: 23 × 2 = 46 W. 46 ÷ 230 = 0.2 A. The current ratio is the inverse of the voltage ratio."},
  {"id":"G-079","section":4,"question":"A transformer has a turns ratio of 1:4 (primary:secondary). With 12 V on the primary, the secondary voltage is:","correct":"48 V","wrong":["3 V","12 V","16 V"],"explain":"Voltage ratio equals turns ratio: 12 × 4 = 48 V."},
  {"id":"D-001","section":4,"question":"The circuit symbol shown is a:","correct":"Resistor","wrong":["Capacitor","Fuse","Inductor"],"explain":"A plain rectangle with a lead each end is the resistor symbol (zig-zag is the older style).","image":"assets/questions/sym-resistor.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-002","section":4,"question":"The circuit symbol shown is a:","correct":"Capacitor","wrong":["Battery","Resistor","Diode"],"explain":"Two parallel plates with a gap: a fixed capacitor.","image":"assets/questions/sym-capacitor.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-003","section":4,"question":"The circuit symbol shown is a:","correct":"Electrolytic (polarised) capacitor","wrong":["Variable capacitor","Battery","Zener diode"],"explain":"One curved or solid plate and a + marking: a polarised (electrolytic) capacitor. Connect it the right way round.","image":"assets/questions/sym-electrolytic.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-004","section":4,"question":"The circuit symbol shown is a:","correct":"Variable capacitor","wrong":["Electrolytic capacitor","Variable resistor","Varactor diode"],"explain":"A capacitor with a diagonal arrow through it is a variable capacitor.","image":"assets/questions/sym-varcap.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-005","section":4,"question":"The circuit symbol shown is a:","correct":"Inductor","wrong":["Transformer","Resistor","Fuse"],"explain":"A series of loops (turns of wire): an inductor or coil.","image":"assets/questions/sym-inductor.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-006","section":4,"question":"The circuit symbol shown is a:","correct":"Iron-cored transformer","wrong":["Two inductors in series","Air-cored capacitor","Relay"],"explain":"Two coils with parallel lines between them: a transformer with an iron (laminated) core.","image":"assets/questions/sym-transformer.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-007","section":4,"question":"The circuit symbol shown is a:","correct":"Diode","wrong":["Zener diode","Varactor diode","LED"],"explain":"A triangle pointing at a straight bar: a diode. Conventional current flows in the direction of the arrow.","image":"assets/questions/sym-diode.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-008","section":4,"question":"The circuit symbol shown is a:","correct":"Zener diode","wrong":["Diode","Varactor diode","LED"],"explain":"The bar with bent ends (like a Z) marks a Zener diode, used as a voltage regulator.","image":"assets/questions/sym-zener.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-009","section":4,"question":"The circuit symbol shown is a:","correct":"Varactor (varicap) diode","wrong":["Zener diode","Electrolytic capacitor","LED"],"explain":"A diode combined with capacitor plates: a varactor, a voltage-variable capacitor.","image":"assets/questions/sym-varactor.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-010","section":4,"question":"The circuit symbol shown is a:","correct":"Light-emitting diode (LED)","wrong":["Photodiode receiving light","Zener diode","Varactor diode"],"explain":"A diode with arrows pointing away from it emits light: an LED.","image":"assets/questions/sym-led.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-011","section":4,"question":"The circuit symbol shown is a:","correct":"Fuse","wrong":["Resistor","Switch","Capacitor"],"explain":"A rectangle with the line running straight through it: a fuse.","image":"assets/questions/sym-fuse.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-012","section":4,"question":"The circuit symbol shown is a:","correct":"Battery (multi-cell)","wrong":["Capacitor","Earth","Fuse"],"explain":"Alternating long and short plates: a battery of cells. The long plate is positive.","image":"assets/questions/sym-battery.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-013","section":4,"question":"The circuit symbol shown represents:","correct":"An earth (ground) connection","wrong":["A battery","A capacitor","An antenna"],"explain":"Horizontal lines getting shorter: an earth connection.","image":"assets/questions/sym-earth.svg","imageAlt":"A circuit symbol (identify it)"},
  {"id":"D-014","section":4,"question":"The symbol shown is a:","correct":"NPN bipolar transistor","wrong":["PNP bipolar transistor","N-channel field effect transistor","Zener diode"],"explain":"The emitter arrow points OUT, away from the base: NPN ('Not Pointing iN').","image":"assets/questions/sym-npn.svg","imageAlt":"Transistor symbol with base, collector and emitter labelled"},
  {"id":"D-015","section":4,"question":"The symbol shown is a:","correct":"PNP bipolar transistor","wrong":["NPN bipolar transistor","N-channel field effect transistor","Zener diode"],"explain":"The emitter arrow points IN towards the base: PNP ('Pointing iN').","image":"assets/questions/sym-pnp.svg","imageAlt":"Transistor symbol with base, collector and emitter labelled"},
  {"id":"D-016","section":4,"question":"The symbol shown, with gate (G), drain (D) and source (S), is a:","correct":"Field effect transistor (FET)","wrong":["NPN bipolar transistor","PNP bipolar transistor","Varactor diode"],"explain":"Gate, drain and source terminals identify a field effect transistor. Bipolar transistors have base, collector and emitter.","image":"assets/questions/sym-fet.svg","imageAlt":"Transistor symbol with gate, drain and source labelled"},
  {"id":"D-017","section":4,"question":"In the transistor symbol shown, the arrow is on the:","correct":"Emitter","wrong":["Base","Collector","Gate"],"explain":"The arrow is always on the emitter. Its direction tells you NPN (out) or PNP (in).","image":"assets/questions/sym-npn-unlab.svg","imageAlt":"Unlabelled bipolar transistor symbol"},
  {"id":"D-018","section":4,"question":"The amplifier shown, with the input on the base, the output taken from the collector and the emitter connected to the common line, is a:","correct":"Common-emitter amplifier using an NPN transistor","wrong":["Common-emitter amplifier using a PNP transistor","Common-source amplifier using a FET","Common-base amplifier using an NPN transistor"],"explain":"The emitter is common to input and output (common emitter), and the arrow points out of the emitter (NPN).","image":"assets/questions/cct-common-emitter.svg","imageAlt":"Transistor amplifier circuit"},
  {"id":"D-019","section":4,"question":"The amplifier shown, with the input on the gate, the output from the drain and the source connected to the common line, is a:","correct":"Common-source FET amplifier","wrong":["Common-emitter bipolar amplifier","Common-drain FET amplifier","Bridge rectifier"],"explain":"For a FET, source common to input and output is the common-source configuration.","image":"assets/questions/cct-common-source.svg","imageAlt":"FET amplifier circuit"},
  {"id":"D-020","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"10 kΩ ±5%","wrong":["100 kΩ ±5%","1 kΩ ±5%","10 kΩ ±10%"],"explain":"Brown = 1  black = 0  orange = ×1 000 → 10 kΩ. Gold = ±5%.","image":"assets/questions/res-1.svg","imageAlt":"Resistor with colour bands: brown, black, orange, gold (band colours also printed under the picture)"},
  {"id":"D-021","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"4.7 kΩ ±5%","wrong":["47 kΩ ±5%","470 Ω ±5%","4.7 kΩ ±10%"],"explain":"Yellow = 4  violet = 7  red = ×100 → 4.7 kΩ. Gold = ±5%.","image":"assets/questions/res-2.svg","imageAlt":"Resistor with colour bands: yellow, violet, red, gold (band colours also printed under the picture)"},
  {"id":"D-022","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"22 kΩ ±10%","wrong":["220 kΩ ±10%","2.2 kΩ ±10%","22 kΩ ±5%"],"explain":"Red = 2  red = 2  orange = ×1 000 → 22 kΩ. Silver = ±10%.","image":"assets/questions/res-3.svg","imageAlt":"Resistor with colour bands: red, red, orange, silver (band colours also printed under the picture)"},
  {"id":"D-023","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"33 Ω ±5%","wrong":["330 Ω ±5%","3.3 Ω ±5%","33 Ω ±10%"],"explain":"Orange = 3  orange = 3  black = ×1 → 33 Ω. Gold = ±5%.","image":"assets/questions/res-4.svg","imageAlt":"Resistor with colour bands: orange, orange, black, gold (band colours also printed under the picture)"},
  {"id":"D-024","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"560 Ω ±20%","wrong":["5.6 kΩ ±20%","56 Ω ±20%","560 Ω ±5%"],"explain":"Green = 5  blue = 6  brown = ×10 → 560 Ω. No tolerance band = ±20%.","image":"assets/questions/res-5.svg","imageAlt":"Resistor with colour bands: green, blue, brown (band colours also printed under the picture)"},
  {"id":"D-025","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"180 kΩ ±5%","wrong":["1.8 MΩ ±5%","18 kΩ ±5%","180 kΩ ±10%"],"explain":"Brown = 1  grey = 8  yellow = ×10 000 → 180 kΩ. Gold = ±5%.","image":"assets/questions/res-6.svg","imageAlt":"Resistor with colour bands: brown, grey, yellow, gold (band colours also printed under the picture)"},
  {"id":"D-026","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"68 Ω ±5%","wrong":["680 Ω ±5%","6.8 Ω ±5%","68 Ω ±10%"],"explain":"Blue = 6  grey = 8  black = ×1 → 68 Ω. Gold = ±5%.","image":"assets/questions/res-7.svg","imageAlt":"Resistor with colour bands: blue, grey, black, gold (band colours also printed under the picture)"},
  {"id":"D-027","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"750 Ω ±10%","wrong":["7.5 kΩ ±10%","75 Ω ±10%","750 Ω ±5%"],"explain":"Violet = 7  green = 5  brown = ×10 → 750 Ω. Silver = ±10%.","image":"assets/questions/res-8.svg","imageAlt":"Resistor with colour bands: violet, green, brown, silver (band colours also printed under the picture)"},
  {"id":"D-028","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"1.2 MΩ ±5%","wrong":["12 MΩ ±5%","120 kΩ ±5%","1.2 MΩ ±10%"],"explain":"Brown = 1  red = 2  green = ×100 000 → 1.2 MΩ. Gold = ±5%.","image":"assets/questions/res-9.svg","imageAlt":"Resistor with colour bands: brown, red, green, gold (band colours also printed under the picture)"},
  {"id":"D-029","section":4,"question":"What is the value and tolerance of the resistor shown?","correct":"910 Ω ±5%","wrong":["9.1 kΩ ±5%","91 Ω ±5%","910 Ω ±10%"],"explain":"White = 9  brown = 1  brown = ×10 → 910 Ω. Gold = ±5%.","image":"assets/questions/res-10.svg","imageAlt":"Resistor with colour bands: white, brown, brown, gold (band colours also printed under the picture)"},
  {"id":"D-030","section":4,"question":"What is the total resistance between A and B in the circuit shown?","correct":"1 kΩ","wrong":["100 Ω","1 200 Ω","66 Ω"],"explain":"In series, resistances add: 100 + 220 + 680 = 1 000 Ω = 1 kΩ.","image":"assets/questions/net-series3.svg","imageAlt":"Resistor network between terminals A and B"},
  {"id":"D-031","section":4,"question":"What is the total resistance between A and B in the circuit shown?","correct":"110 Ω","wrong":["440 Ω","220 Ω","55 Ω"],"explain":"Two equal resistors in parallel = half of one: 220 ÷ 2 = 110 Ω.","image":"assets/questions/net-par2.svg","imageAlt":"Resistor network between terminals A and B"},
  {"id":"D-032","section":4,"question":"What is the total resistance between A and B in the circuit shown?","correct":"11 Ω","wrong":["99 Ω","33 Ω","16.5 Ω"],"explain":"Three equal resistors in parallel: 33 ÷ 3 = 11 Ω.","image":"assets/questions/net-par3.svg","imageAlt":"Resistor network between terminals A and B"},
  {"id":"D-033","section":4,"question":"What is the total resistance between A and B in the circuit shown?","correct":"100 Ω","wrong":["250 Ω","150 Ω","75 Ω"],"explain":"Parallel pair: 100 ÷ 2 = 50 Ω. Add the series 50 Ω: 50 + 50 = 100 Ω.","image":"assets/questions/net-sp1.svg","imageAlt":"Resistor network between terminals A and B"},
  {"id":"D-034","section":4,"question":"What is the total resistance between A and B in the circuit shown?","correct":"1 kΩ","wrong":["4 kΩ","2 kΩ","500 Ω"],"explain":"Each branch is 1 k + 1 k = 2 kΩ. Two equal 2 kΩ branches in parallel = 1 kΩ.","image":"assets/questions/net-sp2.svg","imageAlt":"Resistor network between terminals A and B"},
  {"id":"D-035","section":4,"question":"What is the total capacitance between A and B in the circuit shown?","correct":"94 nF","wrong":["23.5 nF","47 nF","188 nF"],"explain":"Capacitors in parallel add: 47 + 47 = 94 nF.","image":"assets/questions/net-cap-par.svg","imageAlt":"Two capacitors in parallel"},
  {"id":"D-036","section":4,"question":"What is the total capacitance between A and B in the circuit shown?","correct":"11 pF","wrong":["44 pF","22 pF","5.5 pF"],"explain":"Two equal capacitors in series = half of one: 22 ÷ 2 = 11 pF.","image":"assets/questions/net-cap-ser.svg","imageAlt":"Two capacitors in series"},
  {"id":"D-037","section":4,"question":"In the circuit shown, the 12 V battery drives a current of 0.5 A, measured on the ammeter. The value of R is:","correct":"24 Ω","wrong":["6 Ω","12.5 Ω","0.04 Ω"],"explain":"R = E / I = 12 / 0.5 = 24 Ω.","image":"assets/questions/cct-ohm.svg","imageAlt":"Battery, resistor R and ammeter in a single loop"},
  {"id":"D-039","section":4,"question":"The power supply circuit shown is a:","correct":"Half-wave rectifier","wrong":["Full-wave (centre-tap) rectifier","Bridge rectifier","Zener regulator"],"explain":"A single diode conducting on one half of each cycle is a half-wave rectifier. Ripple frequency equals the input frequency.","image":"assets/questions/rect-half.svg","imageAlt":"Transformer feeding a single diode and load"},
  {"id":"D-040","section":4,"question":"The power supply circuit shown is a:","correct":"Full-wave rectifier using a centre-tapped transformer","wrong":["Half-wave rectifier","Bridge rectifier","Voltage doubler"],"explain":"Two diodes and a centre-tapped secondary give full-wave rectification. Ripple is twice the mains frequency.","image":"assets/questions/rect-full.svg","imageAlt":"Centre-tapped transformer with two diodes feeding a load"},
  {"id":"D-041","section":4,"question":"A rectifier like the one shown, which uses four diodes and no centre tap on the transformer, is a:","correct":"Bridge rectifier","wrong":["Half-wave rectifier","Centre-tap full-wave rectifier","Voltage regulator"],"explain":"Four diodes in a bridge give full-wave output without needing a centre-tapped transformer.","image":"assets/questions/rect-bridge.svg","imageAlt":"Transformer feeding a four-diode bridge and load"},
  {"id":"D-042","section":4,"question":"If the rectifier shown is fed from 50 Hz mains, the ripple frequency at the load is:","correct":"100 Hz","wrong":["50 Hz","25 Hz","200 Hz"],"explain":"A bridge rectifier is full-wave, so ripple is twice the supply frequency: 100 Hz.","image":"assets/questions/rect-bridge.svg","imageAlt":"Transformer feeding a four-diode bridge and load"},
  {"id":"D-043","section":4,"question":"For the waveform shown, the frequency is:","correct":"50 Hz","wrong":["20 Hz","100 Hz","500 Hz"],"explain":"One full cycle takes 20 ms. f = 1 / T = 1 / 0.02 = 50 Hz.","image":"assets/questions/sine-1.svg","imageAlt":"One cycle of a sine wave, peak 50 V, one cycle lasting 20 ms"},
  {"id":"D-044","section":4,"question":"For the waveform shown, the RMS voltage is approximately:","correct":"35 V","wrong":["50 V","100 V","71 V"],"explain":"RMS = 0.707 × peak = 0.707 × 50 ≈ 35 V.","image":"assets/questions/sine-1.svg","imageAlt":"One cycle of a sine wave, peak 50 V, one cycle lasting 20 ms"},
  {"id":"D-045","section":4,"question":"For the waveform shown, the peak-to-peak voltage is:","correct":"20 V","wrong":["10 V","7.07 V","14.1 V"],"explain":"Peak-to-peak is twice the peak: 2 × 10 = 20 V.","image":"assets/questions/sine-2.svg","imageAlt":"One cycle of a sine wave, peak 10 V, one cycle lasting 1 ms"},
  {"id":"D-046","section":4,"question":"For the waveform shown, the frequency is:","correct":"1 kHz","wrong":["1 Hz","100 Hz","10 kHz"],"explain":"T = 1 ms, so f = 1 / 0.001 = 1 000 Hz = 1 kHz.","image":"assets/questions/sine-2.svg","imageAlt":"One cycle of a sine wave, peak 10 V, one cycle lasting 1 ms"},
  {"id":"P1-18","section":5,"question":"In an SSB transmitter, the balanced modulator produces:","correct":"A double sideband signal with the carrier suppressed","wrong":["A single sideband signal with full carrier","A frequency modulated signal","An amplified audio signal"],"explain":"The balanced modulator suppresses the carrier and leaves both sidebands (DSB). A filter then removes the unwanted sideband."},
  {"id":"P1-19","section":5,"question":"Signals of 7 MHz and 9 MHz are fed into a mixer. The main new frequencies produced are:","correct":"2 MHz and 16 MHz","wrong":["7 MHz and 9 MHz only","63 MHz","8 MHz"],"explain":"A mixer produces the difference (9 − 7 = 2 MHz) and sum (9 + 7 = 16 MHz) of its inputs. The unwanted one is filtered out."},
  {"id":"P1-20","section":5,"question":"In frequency modulation, 'peak deviation' means:","correct":"The maximum change in carrier frequency from its unmodulated value","wrong":["The maximum change in carrier amplitude","The total bandwidth of the signal","The drift of the oscillator over time"],"explain":"Peak deviation is the largest frequency swing away from the resting carrier frequency."},
  {"id":"P1-21","section":5,"question":"Which of these modes requires a linear power amplifier?","correct":"SSB","wrong":["FM","CW (Morse)","FSK"],"explain":"SSB (and AM) must be amplified linearly to avoid distortion and splatter. FM, CW and FSK have constant amplitude and can use non-linear (Class C) amplifiers."},
  {"id":"P1-22","section":5,"question":"An amplifier draws 200 W of DC input power and delivers 120 W of RF output. Its efficiency is:","correct":"60%","wrong":["40%","167%","80%"],"explain":"Efficiency = Pout / Pin × 100 = 120 / 200 × 100 = 60%."},
  {"id":"P1-23","section":5,"question":"The automatic level control (ALC) in a transmitter:","correct":"Limits the drive level to prevent the power amplifier being over-driven","wrong":["Controls the receiver gain","Keeps the oscillator on frequency","Switches the antenna between transmit and receive"],"explain":"ALC feeds back from the PA to reduce drive, preventing over-driving, distortion and splatter."},
  {"id":"P1-24","section":5,"question":"Over-modulation of an AM transmitter will cause:","correct":"Harmonics and spurious emissions, widening the transmitted bandwidth (splatter)","wrong":["A cleaner, narrower signal","Lower frequency drift","Improved receiver selectivity"],"explain":"Over-modulation distorts the waveform, generating harmonics/spurious signals that spread into adjacent channels."},
  {"id":"P1-25","section":5,"question":"The selectivity of a receiver is its ability to:","correct":"Separate the wanted signal from unwanted signals on nearby frequencies","wrong":["Receive very weak signals","Keep the audio level constant","Stay on frequency over time"],"explain":"Selectivity = rejecting nearby unwanted signals. Sensitivity is about receiving weak signals."},
  {"id":"P1-26","section":5,"question":"In a superheterodyne receiver, the incoming RF signal is converted to the intermediate frequency by the:","correct":"Mixer and local oscillator","wrong":["Detector","Audio amplifier","AGC circuit"],"explain":"The mixer combines the RF signal with the local oscillator to produce the IF. Together they form the frequency converter."},
  {"id":"P1-27","section":5,"question":"The receiver incremental tune (RIT) control allows you to:","correct":"Adjust the receive frequency slightly without changing the transmit frequency","wrong":["Change the transmitter output power","Adjust the transmit frequency without changing the receive frequency","Increase the IF bandwidth"],"explain":"RIT fine-tunes the receiver only, useful when the other station is slightly off your frequency."},
  {"id":"P2-18","section":5,"question":"In a simple FM transmitter, the stage that varies the oscillator frequency in step with the audio is the:","correct":"Reactance modulator","wrong":["Balanced modulator","Power amplifier","Low-pass filter"],"explain":"A reactance (or varactor) modulator changes the oscillator frequency with the audio, producing FM."},
  {"id":"P2-19","section":5,"question":"An FM transmitter's oscillator runs at 48.5 MHz and is followed by a ×3 frequency multiplier. The output frequency is:","correct":"145.5 MHz","wrong":["51.5 MHz","16.17 MHz","97 MHz"],"explain":"48.5 × 3 = 145.5 MHz. Note the deviation is also multiplied by 3."},
  {"id":"P2-20","section":5,"question":"In amplitude modulation, 'depth of modulation' refers to:","correct":"How much the carrier amplitude is varied by the audio, usually given as a percentage","wrong":["How far the carrier frequency moves","The number of sidebands produced","The power supply voltage"],"explain":"Depth of modulation is the extent of the amplitude variation, e.g. 100% modulation."},
  {"id":"P2-21","section":5,"question":"An advantage of SSB over full-carrier AM is that SSB:","correct":"Uses less bandwidth and is more power-efficient because the carrier and one sideband are removed","wrong":["Has a constant carrier, so it is easier to tune","Can use a non-linear power amplifier","Has better audio fidelity for music"],"explain":"SSB takes about 3 kHz versus about 6–10 kHz for AM, and no power is wasted in a carrier."},
  {"id":"P2-22","section":5,"question":"The bandwidth of a data transmission depends on:","correct":"The data transfer rate and the modulation type","wrong":["Only the transmitter power","Only the antenna gain","The length of the coax"],"explain":"Faster data and some modulation types need more bandwidth."},
  {"id":"P2-23","section":5,"question":"A transmitter rated at 100 W for SSB may need to be run at reduced power for long FM or RTTY transmissions because:","correct":"These modes have a high (near 100%) duty cycle, causing more heating in the PA","wrong":["These modes need more bandwidth","These modes need a linear amplifier","SSB has a higher duty cycle"],"explain":"FM/RTTY run at full output continuously, whereas voice SSB averages about 20–40%, so the PA gets much hotter."},
  {"id":"P2-24","section":5,"question":"The second harmonic of a 7.1 MHz signal is:","correct":"14.2 MHz","wrong":["3.55 MHz","21.3 MHz","7.1 MHz"],"explain":"Harmonics are whole-number multiples: 2 × 7.1 = 14.2 MHz."},
  {"id":"P2-25","section":5,"question":"A 'parasitic oscillation' in a transmitter is:","correct":"An unwanted self-oscillation in an amplifier, usually at a frequency unrelated to the operating frequency","wrong":["The normal output of the carrier oscillator","A wanted harmonic","Fading of the received signal"],"explain":"Parasitics are unwanted oscillations that can cause spurious emissions and interference."},
  {"id":"P2-26","section":5,"question":"The purpose of automatic gain control (AGC) in a receiver is to:","correct":"Keep the audio output fairly constant as the received signal strength varies","wrong":["Keep the transmitter output constant","Tune the receiver automatically","Reduce frequency drift"],"explain":"AGC reduces gain on strong signals and increases it on weak ones."},
  {"id":"P2-27","section":5,"question":"An important characteristic of the IF amplifier in a superheterodyne receiver is that it:","correct":"Operates at a fixed frequency and provides most of the receiver's gain and selectivity","wrong":["Tunes across the whole band","Converts the signal to audio","Operates only on transmit"],"explain":"Because the IF is fixed, it can have high gain and sharp filtering (e.g. crystal or ceramic filters)."},
  {"id":"P3-18","section":5,"question":"In an AM transmitter, the stage that follows the oscillator to isolate it from loading by later stages is the:","correct":"Buffer amplifier","wrong":["Power amplifier","Modulator","Low-pass filter"],"explain":"The buffer protects the oscillator from load changes, improving frequency stability."},
  {"id":"P3-19","section":5,"question":"The correct order of stages in a simple superheterodyne receiver is:","correct":"RF amplifier → mixer (with local oscillator) → IF amplifier → detector → audio amplifier","wrong":["Audio amplifier → detector → IF amplifier → mixer → RF amplifier","Mixer → RF amplifier → audio amplifier → IF amplifier → detector","RF amplifier → detector → mixer → IF amplifier → audio amplifier"],"explain":"Signal path: RF amp, mixer/LO (frequency converter), IF amp, detector (demodulator), audio amp."},
  {"id":"P3-20","section":5,"question":"The combined function of a mixer and a local oscillator is that of a:","correct":"Frequency converter","wrong":["Demodulator","Power amplifier","Voltage regulator"],"explain":"Together they convert a signal from one frequency to another (e.g. RF to IF)."},
  {"id":"P3-21","section":5,"question":"In an FM transmitter, increasing the amplitude (loudness) of the modulating audio causes:","correct":"Greater frequency deviation","wrong":["Greater carrier amplitude","A lower carrier frequency","No change"],"explain":"In FM, audio amplitude sets how far the frequency deviates, and audio frequency sets how fast it deviates."},
  {"id":"P3-22","section":5,"question":"Crystal or ceramic filters are used in the IF stages of a receiver to:","correct":"Improve selectivity","wrong":["Increase transmitter power","Reduce power supply ripple","Act as the local oscillator"],"explain":"They give a narrow, steep-sided passband, rejecting adjacent signals."},
  {"id":"P3-23","section":5,"question":"In a transceiver, the transmitter and receiver often share:","correct":"Oscillators and IF amplifier stages","wrong":["The same audio output speaker only","Nothing; they are completely separate","The power amplifier and detector"],"explain":"Sharing oscillators and IF stages saves parts and keeps TX and RX on the same frequency."},
  {"id":"P3-24","section":5,"question":"Receiver sensitivity refers to:","correct":"The ability to receive weak signals","wrong":["The ability to reject adjacent signals","The stability of the local oscillator","The maximum audio output"],"explain":"Sensitivity is the weakest signal that gives a usable output. Selectivity is the rejection of nearby signals."},
  {"id":"P3-25","section":5,"question":"A receiver's signal-to-noise ratio describes:","correct":"How strong the wanted signal is compared with the background noise. Higher is better","wrong":["The ratio of transmitter to receiver power","The amount of frequency drift","The number of IF stages"],"explain":"A higher SNR gives a clearer, more readable signal."},
  {"id":"P3-26","section":5,"question":"Which of the following is NOT a digital transmission mode?","correct":"SSB voice","wrong":["RTTY","PSK","Packet radio"],"explain":"Morse, RTTY, FSK, PSK and packet are digital transmissions. SSB voice is analogue."},
  {"id":"P3-27","section":5,"question":"Frequency drift in a transmitter should be minimised because it can:","correct":"Move the signal off frequency, causing interference to other stations and loss of contact","wrong":["Increase the output power","Improve audio quality","Reduce harmonics"],"explain":"A drifting signal can wander onto other users and away from the station you're working."},
  {"id":"X-15","section":5,"question":"The manual RF power control on a transmitter should be used to:","correct":"Set the output to the minimum power needed for reliable communication","wrong":["Change the operating band","Adjust the receiver volume","Increase the frequency deviation"],"explain":"Use only the power you need. It reduces interference and EMC problems."},
  {"id":"X-16","section":5,"question":"A disadvantage of FM compared with SSB is that FM:","correct":"Occupies a wider bandwidth","wrong":["Is more affected by amplitude noise","Needs a linear amplifier","Cannot be used on VHF"],"explain":"Voice FM needs much more bandwidth than SSB's roughly 3 kHz."},
  {"id":"X-17","section":5,"question":"An advantage of FM over AM is that FM:","correct":"Is less affected by amplitude noise and static","wrong":["Uses less bandwidth","Needs a linear amplifier","Has a lower duty cycle"],"explain":"Noise mostly affects amplitude, and the FM receiver's limiter removes amplitude variations."},
  {"id":"X-18","section":5,"question":"To demodulate an SSB signal, a receiver re-inserts the missing carrier using a:","correct":"Beat frequency oscillator (BFO)","wrong":["Reactance modulator","Frequency multiplier","Balanced antenna"],"explain":"The BFO (with a product detector) supplies the carrier that was removed at the transmitter."},
  {"id":"X-19","section":5,"question":"A 'linear' amplifier is one whose:","correct":"Output is a faithful, proportionally larger copy of its input","wrong":["Output is always the same regardless of input","Output frequency is a multiple of the input","Output contains strong harmonics"],"explain":"Linear means output is proportional to input, which is needed for SSB and AM."},
  {"id":"X-20","section":5,"question":"Morse code, RTTY, FSK, PSK and packet radio are all examples of:","correct":"Digital transmissions","wrong":["Analogue voice modes","Amplitude modulated voice","Television standards"],"explain":"The syllabus lists all of these as types of digital transmission."},
  {"id":"X-21","section":5,"question":"A band-pass filter at the output of a transmitter:","correct":"Passes the wanted band and attenuates unwanted emissions both above and below it","wrong":["Passes only frequencies below a cut-off","Removes only the carrier","Increases harmonic output"],"explain":"Band-pass filters attenuate spurious signals on both sides of the wanted band. Low-pass filters only attenuate those above it."},
  {"id":"M-001","section":5,"question":"The function of the carrier oscillator in an SSB transmitter is to:","correct":"Generate the RF carrier signal that is fed to the balanced modulator","wrong":["Amplify the microphone audio","Remove the unwanted sideband","Measure the output power"],"explain":"The carrier oscillator supplies RF to the balanced modulator, where it is mixed with audio and then suppressed."},
  {"id":"M-002","section":5,"question":"A variable frequency oscillator (VFO) allows the operator to:","correct":"Tune the operating frequency","wrong":["Change the modulation type","Adjust the microphone gain","Switch between transmit and receive"],"explain":"The VFO is the tunable oscillator that sets the operating frequency."},
  {"id":"M-003","section":5,"question":"In a transmitter, the power amplifier (PA) stage:","correct":"Raises the signal to the final output power level","wrong":["Generates the carrier frequency","Converts RF to audio","Removes the carrier"],"explain":"The PA is the last amplifying stage before the output filter and antenna."},
  {"id":"M-004","section":5,"question":"The output filter of a transmitter is fitted between the power amplifier and the antenna to:","correct":"Attenuate harmonics and other unwanted emissions","wrong":["Increase the deviation","Add the carrier back","Improve the microphone's frequency response"],"explain":"Output filters (usually low-pass) reduce harmonics before they reach the antenna."},
  {"id":"M-005","section":5,"question":"A mixer in a transmitter is often used to:","correct":"Convert a signal generated on one frequency to the wanted operating frequency","wrong":["Amplify the audio","Suppress harmonics","Measure SWR"],"explain":"Mixing a fixed-frequency signal with a VFO moves it to the required output frequency."},
  {"id":"M-006","section":5,"question":"Besides the wanted output, a mixer also produces:","correct":"Unwanted frequencies that usually need to be filtered out","wrong":["Only DC","Nothing else at all","Only the original input frequencies at higher power"],"explain":"Mixers produce sum, difference and other products. Filters select the wanted one."},
  {"id":"M-007","section":5,"question":"In an AM signal, the information (audio) is carried by:","correct":"Variations in the amplitude of the carrier","wrong":["Variations in the frequency of the carrier","On-off keying of the carrier","The phase of the power supply"],"explain":"AM varies the carrier's amplitude in step with the audio."},
  {"id":"M-008","section":5,"question":"In an FM signal, the rate at which the carrier frequency swings back and forth is set by:","correct":"The frequency (pitch) of the modulating audio","wrong":["The loudness of the audio","The transmitter power","The antenna length"],"explain":"Audio pitch sets the rate of deviation. Audio loudness sets the amount of deviation."},
  {"id":"M-009","section":5,"question":"100% modulation of an AM transmitter means that:","correct":"The carrier amplitude varies all the way down to zero and up to twice its unmodulated value","wrong":["The carrier is completely suppressed","The frequency deviation is 100 kHz","The transmitter is switched off"],"explain":"At 100% depth the envelope swings from zero to double the carrier amplitude. More than this is over-modulation."},
  {"id":"M-010","section":5,"question":"A double sideband (DSB) suppressed carrier signal contains:","correct":"The upper and lower sidebands but no carrier","wrong":["Only the carrier","One sideband and the carrier","Only the lower sideband"],"explain":"DSB-SC has both sidebands with the carrier removed. SSB then removes one sideband as well."},
  {"id":"M-011","section":5,"question":"A full-carrier AM signal wastes transmitter power because:","correct":"Much of the power is in the carrier, which carries no information","wrong":["The sidebands carry no information","It has a 20% duty cycle","It needs a non-linear amplifier"],"explain":"The carrier carries no information, yet it takes most of the power in AM."},
  {"id":"M-012","section":5,"question":"A disadvantage of SSB compared with FM for local VHF voice contacts is that SSB:","correct":"Must be tuned accurately for the voice to sound natural","wrong":["Uses more bandwidth","Has a constant carrier","Cannot be used on VHF"],"explain":"An SSB signal that is slightly mistuned sounds high- or low-pitched. FM is more forgiving to tune."},
  {"id":"M-013","section":5,"question":"Compared with voice, a slow-speed Morse (CW) signal occupies:","correct":"A much narrower bandwidth","wrong":["A much wider bandwidth","Exactly the same bandwidth as FM","No bandwidth at all"],"explain":"Slow data rates need little bandwidth. CW occupies only a few hundred Hz or less."},
  {"id":"M-014","section":5,"question":"Sending data at a faster rate generally requires:","correct":"More bandwidth","wrong":["Less bandwidth","A lower frequency band only","No change in bandwidth"],"explain":"Bandwidth increases with data rate (for the same modulation type)."},
  {"id":"M-015","section":5,"question":"A non-linear (Class C) amplifier is suitable for:","correct":"FM and CW signals","wrong":["SSB signals","AM signals with low-level modulation","Any signal where linearity matters"],"explain":"Constant-amplitude signals (FM, CW) are not distorted by non-linear amplification. SSB and AM would be."},
  {"id":"M-016","section":5,"question":"Feeding an SSB signal through a non-linear amplifier will cause:","correct":"Distortion and splatter onto nearby frequencies","wrong":["A cleaner signal","Lower harmonic output","No effect on the signal"],"explain":"SSB needs linear amplification. Non-linear amplification creates distortion products and splatter."},
  {"id":"M-017","section":5,"question":"'Duty cycle' in relation to a transmitter means:","correct":"The proportion of time the transmitter is producing full output","wrong":["The number of hours a transmitter can be used per day","The time between services","The ratio of receive to transmit frequencies"],"explain":"Duty cycle is the fraction of time at full power. It is high for FM and RTTY and low for voice SSB."},
  {"id":"M-018","section":5,"question":"A PA rated at 100 W for SSB voice is used for a long FM transmission. To avoid overheating, it is good practice to:","correct":"Reduce the output power, as the manufacturer recommends for high duty-cycle modes","wrong":["Increase the output power","Disconnect the antenna","Switch the ALC off"],"explain":"Continuous-carrier modes heat the PA much more, so run reduced power or short overs."},
  {"id":"M-019","section":5,"question":"Excessive ALC action, shown by a high ALC meter reading on SSB, usually indicates:","correct":"Too much microphone gain or drive, which can cause distortion","wrong":["Too little drive","A perfect antenna match","Low supply voltage only"],"explain":"Reduce mic gain or drive until the ALC reading sits within the manufacturer's range."},
  {"id":"M-020","section":5,"question":"An oscillator that drifts slowly in frequency on transmit will:","correct":"Move the signal off the agreed frequency, possibly onto other users","wrong":["Increase the output power","Improve audio quality","Reduce bandwidth"],"explain":"Drift causes interference and makes the signal hard to follow. Minimising drift is important."},
  {"id":"M-021","section":5,"question":"Harmonics radiated by a transmitter can:","correct":"Cause interference to other services on multiples of the operating frequency","wrong":["Only be heard on the operating frequency","Improve the signal","Never leave the transmitter"],"explain":"Harmonics fall on 2×, 3× and so on of the operating frequency and can interfere with other services."},
  {"id":"M-022","section":5,"question":"Spurious emissions are:","correct":"Unwanted signals radiated on frequencies other than the wanted one","wrong":["The wanted sidebands of an SSB signal","Signals received from distant stations","The carrier of an FM signal"],"explain":"Spurious emissions include harmonics, parasitics and mixer products. Filters and good adjustment minimise them."},
  {"id":"M-023","section":5,"question":"A parasitic oscillation in a power amplifier may be indicated by:","correct":"Unexpected output, heating or interference on frequencies unrelated to the operating frequency","wrong":["A perfect 1:1 SWR","Improved efficiency","Lower current draw"],"explain":"Parasitics show up as spurious signals, instability or unexplained heating."},
  {"id":"M-024","section":5,"question":"Receiver sensitivity is often given as the signal level needed to produce a stated:","correct":"Signal-to-noise ratio at the output","wrong":["Transmit power","Antenna length","IF frequency"],"explain":"For example, 0.2 µV for 10 dB S+N/N. A smaller figure means a more sensitive receiver."},
  {"id":"M-025","section":5,"question":"A receiver with poor selectivity will:","correct":"Let strong signals on nearby frequencies interfere with the wanted signal","wrong":["Be unable to hear weak signals","Drift in frequency","Have no AGC"],"explain":"Selectivity is about rejecting nearby signals, mainly set by the IF filters."},
  {"id":"M-026","section":5,"question":"A receiver's signal-to-noise ratio of 20 dB is better than one of 10 dB because:","correct":"The wanted signal is further above the noise","wrong":["The noise is louder","It uses less bandwidth","It has a lower IF"],"explain":"A higher SNR means a cleaner, more readable signal."},
  {"id":"M-027","section":5,"question":"The local oscillator in a superheterodyne receiver:","correct":"Combines with the incoming signal in the mixer to produce the IF","wrong":["Demodulates the audio","Amplifies the audio","Rectifies the mains"],"explain":"LO plus mixer form the frequency converter that produces the intermediate frequency."},
  {"id":"M-028","section":5,"question":"The demodulator (detector) stage of a receiver:","correct":"Recovers the original audio or data from the IF signal","wrong":["Generates the carrier","Filters harmonics from the transmitter","Provides the local oscillator signal"],"explain":"The detector extracts the modulation. The audio amplifier then drives the speaker."},
  {"id":"M-029","section":5,"question":"The RF amplifier at the front of a receiver mainly:","correct":"Amplifies weak incoming signals before the mixer","wrong":["Drives the loudspeaker","Converts the signal to audio","Generates the BFO signal"],"explain":"The RF amplifier improves sensitivity and provides some selectivity before the mixer."},
  {"id":"M-030","section":5,"question":"An important reason for using a fixed intermediate frequency in a superhet is that:","correct":"Filters and amplifiers can be optimised for one frequency","wrong":["It removes the need for an antenna","It allows the receiver to work without power","It makes the local oscillator unnecessary"],"explain":"A fixed IF allows high gain and sharp, stable filtering regardless of the received frequency."},
  {"id":"M-031","section":5,"question":"A narrow crystal filter in the IF of an HF receiver is especially useful for:","correct":"Separating closely spaced CW or SSB signals","wrong":["Increasing transmitter power","Reducing mains hum","Receiving FM broadcast stations"],"explain":"Narrow crystal filters give the steep selectivity needed on crowded HF bands."},
  {"id":"M-032","section":5,"question":"Without AGC, a receiver tuned from a weak signal to a very strong signal would:","correct":"Produce a sudden, very loud audio output","wrong":["Become more selective","Change its IF","Stop working permanently"],"explain":"AGC automatically reduces gain on strong signals so the volume stays fairly constant."},
  {"id":"M-033","section":5,"question":"In a transceiver, sharing the same oscillators between transmit and receive helps to:","correct":"Keep the transmitter and receiver on the same frequency","wrong":["Increase the receiver bandwidth","Remove the need for a power supply","Increase harmonics"],"explain":"Shared oscillators mean you transmit where you are listening (unless RIT or split is used)."},
  {"id":"M-034","section":5,"question":"After a contact where you used RIT to tune in the other station, you should:","correct":"Switch RIT off (or reset it to zero) so you receive on your transmit frequency again","wrong":["Leave it on permanently","Increase power","Change band"],"explain":"Leaving RIT on can cause you to call stations off your own transmit frequency."},
  {"id":"M-035","section":5,"question":"An advantage of PSK and similar digital modes is that they:","correct":"Can be decoded at low signal levels using a narrow bandwidth","wrong":["Need very high power","Use more bandwidth than FM","Cannot be used on HF"],"explain":"Narrow-band digital modes like PSK work well with weak signals."},
  {"id":"G-080","section":5,"question":"An amplifier has a DC input power of 100 W and an RF output of 50 W. Its efficiency is:","correct":"50%","wrong":["200%","25%","65%"],"explain":"Efficiency = 50 / 100 × 100 = 50%."},
  {"id":"G-081","section":5,"question":"An amplifier has a DC input power of 250 W and an RF output of 150 W. Its efficiency is:","correct":"60%","wrong":["40%","166.7%","30%"],"explain":"Efficiency = 150 / 250 × 100 = 60%."},
  {"id":"G-082","section":5,"question":"An amplifier has a DC input power of 80 W and an RF output of 60 W. Its efficiency is:","correct":"75%","wrong":["25%","133.3%","37.5%"],"explain":"Efficiency = 60 / 80 × 100 = 75%."},
  {"id":"G-083","section":5,"question":"An amplifier has a DC input power of 500 W and an RF output of 350 W. Its efficiency is:","correct":"70%","wrong":["30%","142.9%","35%"],"explain":"Efficiency = 350 / 500 × 100 = 70%."},
  {"id":"G-084","section":5,"question":"An amplifier has a DC input power of 30 W and an RF output of 12 W. Its efficiency is:","correct":"40%","wrong":["60%","250%","20%"],"explain":"Efficiency = 12 / 30 × 100 = 40%."},
  {"id":"G-085","section":5,"question":"An amplifier with 70% efficiency delivers 70 W of RF output. The DC input power is:","correct":"100 W","wrong":["49 W","70 W","140 W"],"explain":"Pin = Pout ÷ efficiency = 70 ÷ 0.70 = 100 W."},
  {"id":"G-086","section":5,"question":"The third harmonic of a 3.6 MHz signal is:","correct":"10.8 MHz","wrong":["7.2 MHz","1.2 MHz","6.6 MHz"],"explain":"Harmonics are whole-number multiples: 3 × 3.6 = 10.8 MHz."},
  {"id":"G-087","section":5,"question":"The second harmonic of a 14.1 MHz signal is:","correct":"28.2 MHz","wrong":["42.3 MHz","7.05 MHz","16.1 MHz"],"explain":"Harmonics are whole-number multiples: 2 × 14.1 = 28.2 MHz."},
  {"id":"G-088","section":5,"question":"The third harmonic of a 50.2 MHz signal is:","correct":"150.6 MHz","wrong":["100.4 MHz","16.73 MHz","53.2 MHz"],"explain":"Harmonics are whole-number multiples: 3 × 50.2 = 150.6 MHz."},
  {"id":"G-089","section":5,"question":"The third harmonic of a 146 MHz signal is:","correct":"438 MHz","wrong":["292 MHz","48.67 MHz","149 MHz"],"explain":"Harmonics are whole-number multiples: 3 × 146 = 438 MHz."},
  {"id":"G-090","section":5,"question":"An oscillator at 12 MHz is followed by frequency multipliers with a total multiplication of ×12. The output frequency is:","correct":"144 MHz","wrong":["24 MHz","1 MHz","288 MHz"],"explain":"12 × 12 = 144 MHz."},
  {"id":"G-091","section":5,"question":"An oscillator at 36.5 MHz is followed by frequency multipliers with a total multiplication of ×4. The output frequency is:","correct":"146 MHz","wrong":["40.5 MHz","9.125 MHz","292 MHz"],"explain":"36.5 × 4 = 146 MHz."},
  {"id":"G-092","section":5,"question":"An oscillator at 72.5 MHz is followed by frequency multipliers with a total multiplication of ×2. The output frequency is:","correct":"145 MHz","wrong":["74.5 MHz","36.25 MHz","290 MHz"],"explain":"72.5 × 2 = 145 MHz."},
  {"id":"G-093","section":5,"question":"Signals of 10.7 MHz and 145 MHz are fed into a mixer. The sum and difference frequencies produced are:","correct":"155.7 MHz and 134.3 MHz","wrong":["1 552 MHz and 13.55 MHz","10.7 MHz and 145 MHz only","311.4 MHz and 268.6 MHz"],"explain":"Sum: 145 + 10.7 = 155.7 MHz. Difference: 145 − 10.7 = 134.3 MHz."},
  {"id":"G-094","section":5,"question":"Signals of 5 MHz and 9 MHz are fed into a mixer. The sum and difference frequencies produced are:","correct":"14 MHz and 4 MHz","wrong":["45 MHz and 1.8 MHz","5 MHz and 9 MHz only","28 MHz and 8 MHz"],"explain":"Sum: 9 + 5 = 14 MHz. Difference: 9 − 5 = 4 MHz."},
  {"id":"G-095","section":5,"question":"Signals of 455 kHz and 1 MHz are fed into a mixer. The sum and difference frequencies produced are:","correct":"1.455 MHz and 545 kHz","wrong":["455 kHz and 2.198 MHz","455 kHz and 1 MHz only","2.91 MHz and 1.09 MHz"],"explain":"Sum: 1 + 0.455 = 1.455 MHz. Difference: 1 − 0.455 = 545 kHz."},
  {"id":"G-096","section":5,"question":"A receiver uses a 10.7 MHz IF. To receive 100.0 MHz, the local oscillator could be on:","correct":"110.7 MHz","wrong":["100.0 MHz","10.7 MHz","200.0 MHz"],"explain":"The mixer output is the difference: 110.7 − 100.0 = 10.7 MHz. (89.3 MHz would also work.)"},
  {"id":"D-051","section":5,"question":"In the receiver block diagram shown, the stage marked ? is the:","correct":"Mixer (with local oscillator)","wrong":["Detector","Audio amplifier","Balanced modulator"],"explain":"In a superhet the stage after the RF amplifier is the mixer, which, with the local oscillator, converts the signal to the IF.","image":"assets/questions/bd-superhet-mixer.svg","imageAlt":"Receiver block diagram: RF amplifier → ? → IF amplifier → Detector → Audio amplifier"},
  {"id":"D-052","section":5,"question":"In the receiver block diagram shown, the stage marked ? is the:","correct":"IF amplifier","wrong":["RF amplifier","Power amplifier","Frequency multiplier"],"explain":"Between the mixer and the detector is the IF amplifier. It gives most of the gain and selectivity at a fixed frequency.","image":"assets/questions/bd-superhet-if.svg","imageAlt":"Receiver block diagram: RF amplifier → Mixer → ? → Detector → Audio amplifier"},
  {"id":"D-053","section":5,"question":"In the receiver block diagram shown, the stage marked ? is the:","correct":"Detector (demodulator)","wrong":["Mixer","IF amplifier","Oscillator"],"explain":"The detector recovers the audio from the IF signal before the audio amplifier.","image":"assets/questions/bd-superhet-det.svg","imageAlt":"Receiver block diagram: RF amplifier → Mixer → IF amplifier → ? → Audio amplifier"},
  {"id":"D-054","section":5,"question":"In the transmitter block diagram shown, the stage marked ? is the:","correct":"Sideband filter","wrong":["Frequency multiplier","Detector","Reactance modulator"],"explain":"After the balanced modulator (DSB, carrier suppressed), a filter removes the unwanted sideband.","image":"assets/questions/bd-ssb-filter.svg","imageAlt":"Transmitter block diagram: Audio amplifier → Balanced modulator → ? → Mixer → Power amplifier"},
  {"id":"D-055","section":5,"question":"In the transmitter block diagram shown, the stage marked ? is the:","correct":"Balanced modulator","wrong":["Reactance modulator","Detector","IF amplifier"],"explain":"The balanced modulator combines audio and carrier and suppresses the carrier.","image":"assets/questions/bd-ssb-bal.svg","imageAlt":"Transmitter block diagram: Audio amplifier → ? → Sideband filter → Mixer → Power amplifier"},
  {"id":"D-056","section":5,"question":"In the transmitter block diagram shown, the stage marked ? is the:","correct":"Frequency multiplier","wrong":["Balanced modulator","Sideband filter","Detector"],"explain":"In this FM transmitter, a multiplier raises the oscillator frequency (and deviation) to the output frequency.","image":"assets/questions/bd-fm-mult.svg","imageAlt":"Transmitter block diagram: Audio amplifier → Reactance modulator → Oscillator → ? → Power amplifier"},
  {"id":"D-057","section":5,"question":"In the transmitter block diagram shown, the stage marked ? is the:","correct":"Reactance modulator","wrong":["Balanced modulator","Product detector","IF amplifier"],"explain":"The reactance (or varactor) modulator varies the oscillator frequency with the audio, producing FM.","image":"assets/questions/bd-fm-react.svg","imageAlt":"Transmitter block diagram: Audio amplifier → ? → Oscillator → Frequency multiplier → Power amplifier"},
  {"id":"D-058","section":5,"question":"In the transmitter block diagram shown, the stage marked ? is the:","correct":"Buffer amplifier","wrong":["Mixer","Detector","Audio amplifier"],"explain":"The buffer follows the oscillator and isolates it from later stages, improving stability.","image":"assets/questions/bd-am-buffer.svg","imageAlt":"Transmitter block diagram: Oscillator → ? → Frequency multiplier → Modulated PA → Low-pass filter"},
  {"id":"D-059","section":5,"question":"In the transmitter block diagram shown, the stage marked ? is the:","correct":"Low-pass filter","wrong":["High-pass filter","IF amplifier","Balanced modulator"],"explain":"A low-pass filter at the output attenuates harmonics before the antenna.","image":"assets/questions/bd-am-lpf.svg","imageAlt":"Transmitter block diagram: Oscillator → Buffer amplifier → Frequency multiplier → Modulated PA → ?"},
  {"id":"P1-28","section":6,"question":"The velocity factor of a transmission line is:","correct":"Always less than 1","wrong":["Always greater than 1","Exactly 1 for coaxial cable","Always 0.5"],"explain":"Radio waves travel more slowly in a line than in free space, so VF is always less than unity (e.g. ~0.66 for solid polyethylene coax)."},
  {"id":"P1-29","section":6,"question":"As the operating frequency increases, the loss in a given length of coaxial cable:","correct":"Increases","wrong":["Decreases","Stays the same","Falls to zero"],"explain":"Line loss increases with frequency, which is why low-loss cable matters at VHF and above."},
  {"id":"P1-30","section":6,"question":"When feeding a half-wave dipole with coaxial cable, a balun is used mainly to:","correct":"Prevent RF current flowing on the outside of the coax and radiating from the feedline","wrong":["Increase the transmitter power","Change the antenna's resonant frequency","Protect the antenna from lightning"],"explain":"A balun (balanced-to-unbalanced) stops common-mode currents and feedline radiation, reducing interference to nearby electronics."},
  {"id":"P1-31","section":6,"question":"An SWR reading generally considered acceptable is:","correct":"1.5:1 or less","wrong":["3:1 or more","Exactly 0:1","10:1"],"explain":"The syllabus states an SWR of 1.5:1 or less is acceptable. 1:1 is a perfect match."},
  {"id":"P1-32","section":6,"question":"An antenna tuning unit (ATU) is fitted at the transmitter end of the coax. Its effect on the SWR in the coax between the ATU and the antenna is:","correct":"None. The SWR on that section of line is unchanged","wrong":["It reduces the SWR on the line to 1:1","It doubles the SWR on the line","It removes all line loss"],"explain":"An ATU at the transmitter only presents a good match to the transmitter. The mismatch, and the SWR, on the line to the antenna is unchanged."},
  {"id":"P1-33","section":6,"question":"Ignoring end effects, the length of a half-wave dipole for 14.2 MHz is approximately:","correct":"10.6 m","wrong":["21.1 m","5.3 m","42.2 m"],"explain":"λ = 300 / f(MHz) = 300 / 14.2 ≈ 21.1 m. Half of this ≈ 10.6 m."},
  {"id":"P1-34","section":6,"question":"The feedpoint impedance of a folded dipole is approximately:","correct":"300 Ω","wrong":["73 Ω","36 Ω","50 Ω"],"explain":"A folded dipole is about four times a simple dipole: 4 × 73 ≈ 292–300 Ω."},
  {"id":"P2-28","section":6,"question":"Standing waves on a transmission line are caused by:","correct":"A mismatch between the line impedance and the load impedance, causing reflected waves","wrong":["Using a balun","A perfectly matched antenna","Low transmitter power"],"explain":"A mismatch reflects power back. The forward and reflected waves combine to form standing waves."},
  {"id":"P2-29","section":6,"question":"Standing wave ratio (SWR) is a measure of:","correct":"The relationship between the forward and reflected waves on a transmission line","wrong":["The transmitter's frequency stability","The gain of the antenna","The velocity factor of the line"],"explain":"SWR compares forward and reflected waves and can be found from voltage, current or power."},
  {"id":"P2-30","section":6,"question":"The feedpoint impedance of a quarter-wave ground plane antenna is approximately:","correct":"36 Ω","wrong":["73 Ω","300 Ω","600 Ω"],"explain":"About 36 Ω. Drooping the radials to about 45° raises it towards 50 Ω."},
  {"id":"P2-31","section":6,"question":"On a half-wave dipole, the current is:","correct":"Maximum at the centre (feedpoint) and minimum at the ends","wrong":["Minimum at the centre and maximum at the ends","The same all along the antenna","Maximum at one end only"],"explain":"Current is maximum at the feedpoint and zero at the ends. Voltage is the opposite."},
  {"id":"P2-32","section":6,"question":"A 50 W transmitter feeds an antenna with a gain of 6 dBd through coax with 3 dB of loss. The ERP is approximately:","correct":"100 W","wrong":["50 W","200 W","25 W"],"explain":"Net gain = +6 − 3 = +3 dB. +3 dB doubles the power: 50 × 2 = 100 W ERP."},
  {"id":"P2-33","section":6,"question":"An antenna made up of a driven element, a reflector behind it and one or more directors in front is a:","correct":"Yagi","wrong":["Folded dipole","Quarter-wave ground plane","End-fed wire"],"explain":"That is the Yagi, a directional beam antenna."},
  {"id":"P2-34","section":6,"question":"A low angle of vertical radiation from an HF antenna is desirable for:","correct":"Long-distance (DX) communication","wrong":["Local ground-wave contacts only","Reducing SWR","Satellite communication directly overhead"],"explain":"Low-angle signals reach the ionosphere at a shallow angle, giving longer hops."},
  {"id":"P3-28","section":6,"question":"Low-loss transmission line is particularly important at VHF and higher frequencies because:","correct":"Line losses increase as frequency increases","wrong":["Line losses decrease as frequency increases","VHF transmitters have more power","The velocity factor is higher at VHF"],"explain":"Loss rises with frequency, so long runs of thin coax waste a lot of power at VHF/UHF."},
  {"id":"P3-29","section":6,"question":"Radiation from the feedline increases the possibility of:","correct":"Interference to nearby electronic devices","wrong":["Better DX performance","Lower SWR","Reduced line loss"],"explain":"Feedline radiation puts RF near household electronics, which is why a balun is used on balanced antennas."},
  {"id":"P3-30","section":6,"question":"Standing waves on a transmission line may:","correct":"Increase the loss in the line","wrong":["Reduce the loss to zero","Increase the transmitter frequency","Improve receiver sensitivity"],"explain":"Voltage/current peaks raise I²R and dielectric losses."},
  {"id":"P3-31","section":6,"question":"An antenna tuning unit (ATU) can:","correct":"Tune out reactance and transform the antenna system impedance to a resistive value suitable for the transmitter","wrong":["Increase the antenna gain by 10 dB","Remove all harmonics automatically","Change the antenna polarisation"],"explain":"An ATU cancels reactance and transforms the impedance, typically to about 50 Ω resistive."},
  {"id":"P3-32","section":6,"question":"Ignoring end effects, the length of a quarter-wave vertical for 146 MHz is approximately:","correct":"51 cm","wrong":["1.03 m","2.05 m","25 cm"],"explain":"λ = 300 / 146 ≈ 2.05 m. A quarter of this ≈ 0.51 m (51 cm)."},
  {"id":"P3-33","section":6,"question":"The feedpoint impedance of a half-wave dipole in free space is approximately:","correct":"73 Ω","wrong":["36 Ω","300 Ω","600 Ω"],"explain":"About 73 Ω. A folded dipole is about 300 Ω and a ¼-wave ground plane about 36 Ω."},
  {"id":"P3-34","section":6,"question":"A 25 W transmitter feeds a 3 dB gain antenna through coax with 3 dB of loss. The ERP is approximately:","correct":"25 W","wrong":["50 W","12.5 W","100 W"],"explain":"+3 dB gain − 3 dB loss = 0 dB net, so ERP equals the transmitter power: 25 W."},
  {"id":"X-22","section":6,"question":"A coaxial cable has a velocity factor of 0.66. Radio waves travel along it at:","correct":"66% of their speed in free space","wrong":["1.66 times their speed in free space","The same speed as in free space","34% of their speed in free space"],"explain":"VF is the ratio of speed in the line to speed in free space: 0.66 = 66%."},
  {"id":"X-23","section":6,"question":"On a half-wave dipole, the voltage is:","correct":"Maximum at the ends and minimum at the centre","wrong":["Maximum at the centre and minimum at the ends","Constant along the length","Zero everywhere"],"explain":"Voltage is the opposite of current: maximum at the open ends."},
  {"id":"X-24","section":6,"question":"An antenna consisting of a single long wire fed at one end, usually through a matching unit, is an:","correct":"End-fed wire antenna","wrong":["Yagi","Folded dipole","Quarter-wave ground plane"],"explain":"That is the end-fed wire. A matching unit or transformer is normally used at the feed end."},
  {"id":"X-25","section":6,"question":"SWR can be determined from measurements of:","correct":"Forward and reflected voltage, current or power","wrong":["Transmitter frequency only","Antenna height only","Receiver S-meter readings only"],"explain":"The syllabus notes SWR can be found from forward and reflected voltage, current or power."},
  {"id":"M-036","section":6,"question":"The physical length of a resonant antenna:","correct":"Decreases as the operating frequency increases","wrong":["Increases as the operating frequency increases","Is the same for all frequencies","Depends only on the transmitter power"],"explain":"Higher frequency means shorter wavelength, so a shorter antenna."},
  {"id":"M-037","section":6,"question":"An open-wire (ladder) line typically has:","correct":"Lower loss than coaxial cable","wrong":["Higher loss than coaxial cable","A velocity factor of exactly 0.5","No characteristic impedance"],"explain":"Open-wire line has low loss and a high velocity factor (about 0.9–0.98)."},
  {"id":"M-038","section":6,"question":"Common coaxial cable used in amateur stations has a characteristic impedance of about:","correct":"50 Ω","wrong":["300 Ω","600 Ω","5 Ω"],"explain":"Most transceivers and coax are 50 Ω. TV coax is usually 75 Ω."},
  {"id":"M-039","section":6,"question":"When the load (antenna) impedance exactly matches the transmission line impedance:","correct":"There is no reflected wave and the SWR is 1:1","wrong":["The SWR is infinite","All power is reflected","Standing waves are at a maximum"],"explain":"With a perfect match all the power is absorbed by the load and there are no standing waves."},
  {"id":"M-040","section":6,"question":"A high SWR can cause:","correct":"Increased line loss and possible damage or power reduction in the transmitter","wrong":["Better DX performance","Lower harmonic output","Improved receiver sensitivity"],"explain":"Reflected power raises line loss. Modern rigs fold back power to protect the PA."},
  {"id":"M-041","section":6,"question":"The purpose of an antenna tuning unit placed at the transmitter is mainly to:","correct":"Present a suitable resistive load (about 50 Ω) to the transmitter","wrong":["Make the antenna resonant on every band","Remove the need for coax","Increase the antenna's gain"],"explain":"It matches the transmitter to the antenna system. It does not change the SWR on the feedline beyond it."},
  {"id":"M-042","section":6,"question":"Moving the ATU from the shack to the antenna feedpoint can:","correct":"Reduce the SWR, and therefore the losses, on the feedline","wrong":["Increase the SWR on the feedline","Change the antenna's polarisation","Make no possible difference"],"explain":"Matching at the antenna means the feedline sees a match, so standing-wave losses on it are reduced."},
  {"id":"M-043","section":6,"question":"Drooping the radials of a quarter-wave ground plane downwards (about 45°):","correct":"Raises the feedpoint impedance towards 50 Ω","wrong":["Lowers the impedance towards 10 Ω","Changes the antenna to horizontal polarisation","Has no effect"],"explain":"With horizontal radials it is about 36 Ω. Drooping them raises it to about 50 Ω for a good coax match."},
  {"id":"M-044","section":6,"question":"On a quarter-wave vertical, the current is maximum:","correct":"At the base (feedpoint)","wrong":["At the top","Halfway up","Equally all along it"],"explain":"Like half a dipole: maximum current at the feedpoint, zero at the tip. Voltage is maximum at the tip."},
  {"id":"M-045","section":6,"question":"The element of a Yagi that is connected to the feedline is the:","correct":"Driven element","wrong":["Reflector","Director","Boom"],"explain":"Only the driven element is fed. The reflector and directors are parasitic elements."},
  {"id":"M-046","section":6,"question":"A Yagi antenna is used mainly because it:","correct":"Concentrates the signal in one direction, giving gain","wrong":["Radiates equally in all directions","Needs no feedline","Works only on HF"],"explain":"A Yagi is a directional beam with gain in its forward direction."},
  {"id":"M-047","section":6,"question":"Antenna gain quoted in dBd is relative to:","correct":"A half-wave dipole","wrong":["An isotropic radiator","A quarter-wave vertical","A dummy load"],"explain":"dBd is relative to a dipole and dBi to an isotropic source (0 dBd = 2.15 dBi)."},
  {"id":"M-048","section":6,"question":"Doubling the transmitter power is an increase of about:","correct":"3 dB","wrong":["6 dB","10 dB","2 dB"],"explain":"×2 ≈ +3 dB, ×4 ≈ +6 dB, ×10 = +10 dB."},
  {"id":"M-049","section":6,"question":"Feedline losses in an antenna system:","correct":"Reduce the ERP","wrong":["Increase the ERP","Have no effect on ERP","Only affect received signals"],"explain":"ERP = transmitter power + antenna gain − line and other losses."},
  {"id":"M-050","section":6,"question":"To reduce feedline loss on a long run to a 70 cm antenna, the best choice is:","correct":"Low-loss, larger-diameter coaxial cable","wrong":["The thinnest available coax","Twin-lead lying on the ground","Extra connectors and adaptors"],"explain":"Loss rises with frequency, so use quality low-loss cable and keep connectors to a minimum."},
  {"id":"G-097","section":6,"question":"Ignoring end effects, a half-wave dipole for 3.6 MHz is approximately:","correct":"41.7 m","wrong":["83.3 m","20.8 m","166.7 m"],"explain":"λ = 300 / 3.6 ≈ 83.33 m. Half of this ≈ 41.7 m."},
  {"id":"G-098","section":6,"question":"Ignoring end effects, a half-wave dipole for 7.1 MHz is approximately:","correct":"21.1 m","wrong":["42.3 m","10.6 m","84.5 m"],"explain":"λ = 300 / 7.1 ≈ 42.25 m. Half of this ≈ 21.1 m."},
  {"id":"G-099","section":6,"question":"Ignoring end effects, a half-wave dipole for 21.2 MHz is approximately:","correct":"7.1 m","wrong":["14.2 m","3.5 m","28.3 m"],"explain":"λ = 300 / 21.2 ≈ 14.15 m. Half of this ≈ 7.1 m."},
  {"id":"G-100","section":6,"question":"Ignoring end effects, a half-wave dipole for 28.5 MHz is approximately:","correct":"5.3 m","wrong":["10.5 m","2.6 m","21.1 m"],"explain":"λ = 300 / 28.5 ≈ 10.53 m. Half of this ≈ 5.3 m."},
  {"id":"G-101","section":6,"question":"Ignoring end effects, a half-wave dipole for 50.2 MHz is approximately:","correct":"3 m","wrong":["6 m","1.5 m","12 m"],"explain":"λ = 300 / 50.2 ≈ 5.976 m. Half of this ≈ 3 m."},
  {"id":"G-102","section":6,"question":"Ignoring end effects, a half-wave dipole for 146 MHz is approximately:","correct":"1 m","wrong":["2.1 m","51 cm","4.1 m"],"explain":"λ = 300 / 146 ≈ 2.055 m. Half of this ≈ 1 m."},
  {"id":"G-103","section":6,"question":"Ignoring end effects, a quarter-wave vertical for 52 MHz is approximately:","correct":"1.44 m","wrong":["2.88 m","5.77 m","72 cm"],"explain":"λ = 300 / 52 ≈ 5.769 m. A quarter of this ≈ 1.44 m."},
  {"id":"G-104","section":6,"question":"Ignoring end effects, a quarter-wave vertical for 438 MHz is approximately:","correct":"17 cm","wrong":["34 cm","68 cm","9 cm"],"explain":"λ = 300 / 438 ≈ 0.6849 m. A quarter of this ≈ 17 cm."},
  {"id":"G-105","section":6,"question":"Ignoring end effects, a quarter-wave vertical for 28.4 MHz is approximately:","correct":"2.64 m","wrong":["5.28 m","10.56 m","1.32 m"],"explain":"λ = 300 / 28.4 ≈ 10.56 m. A quarter of this ≈ 2.64 m."},
  {"id":"G-106","section":6,"question":"Ignoring end effects, a quarter-wave vertical for 7.15 MHz is approximately:","correct":"10.49 m","wrong":["20.98 m","41.96 m","5.24 m"],"explain":"λ = 300 / 7.15 ≈ 41.96 m. A quarter of this ≈ 10.49 m."},
  {"id":"G-107","section":6,"question":"A 10 W transmitter feeds an antenna with 10 dBd gain through coax with negligible loss. The ERP is approximately:","correct":"100 W","wrong":["10 W","200 W","50 W"],"explain":"Net gain = 10 − 0 = +10 dB. +10 dB is ×10, so ERP ≈ 100 W."},
  {"id":"G-108","section":6,"question":"A 100 W transmitter feeds an antenna with 6 dBd gain through coax with 3 dB of loss. The ERP is approximately:","correct":"200 W","wrong":["100 W","400 W","600 W"],"explain":"Net gain = 6 − 3 = +3 dB. +3 dB is ×2, so ERP ≈ 200 W."},
  {"id":"G-109","section":6,"question":"A 5 W transmitter feeds an antenna with 3 dBd gain through coax with negligible loss. The ERP is approximately:","correct":"10 W","wrong":["5 W","20 W","15 W"],"explain":"Net gain = 3 − 0 = +3 dB. +3 dB is ×2, so ERP ≈ 10 W."},
  {"id":"G-110","section":6,"question":"A 50 W transmitter feeds an antenna with 10 dBd gain through coax with negligible loss. The ERP is approximately:","correct":"500 W","wrong":["50 W","1 000 W","250 W"],"explain":"Net gain = 10 − 0 = +10 dB. +10 dB is ×10, so ERP ≈ 500 W."},
  {"id":"G-111","section":6,"question":"A 100 W transmitter feeds an antenna with 0 dBd gain through coax with 3 dB of loss. The ERP is approximately:","correct":"50 W","wrong":["100 W","25 W","300 W"],"explain":"Net gain = 0 − 3 = -3 dB. -3 dB is ×0.5, so ERP ≈ 50 W."},
  {"id":"G-112","section":6,"question":"A 20 W transmitter feeds an antenna with 6 dBd gain through coax with negligible loss. The ERP is approximately:","correct":"80 W","wrong":["20 W","160 W","40 W"],"explain":"Net gain = 6 − 0 = +6 dB. +6 dB is ×4, so ERP ≈ 80 W."},
  {"id":"G-113","section":6,"question":"A 40 W transmitter feeds an antenna with 9 dBd gain through coax with 3 dB of loss. The ERP is approximately:","correct":"160 W","wrong":["40 W","320 W","80 W"],"explain":"Net gain = 9 − 3 = +6 dB. +6 dB is ×4, so ERP ≈ 160 W."},
  {"id":"G-114","section":6,"question":"A 100 W transmitter feeds an antenna with 3 dBd gain through coax with 6 dB of loss. The ERP is approximately:","correct":"50 W","wrong":["100 W","25 W","300 W"],"explain":"Net gain = 3 − 6 = -3 dB. -3 dB is ×0.5, so ERP ≈ 50 W."},
  {"id":"G-115","section":6,"question":"An SWR meter shows 100 W forward. With a perfect match (1:1), the reflected power will be:","correct":"0 W","wrong":["100 W","50 W","1 W"],"explain":"At 1:1 there is no reflection, so reflected power is zero."},
  {"id":"D-060","section":6,"question":"The antenna shown is a:","correct":"Half-wave dipole","wrong":["Folded dipole","Quarter-wave ground plane","Yagi"],"explain":"Two equal λ/4 arms fed at the centre: a half-wave dipole (about 73 Ω).","image":"assets/questions/ant-dipole.svg","imageAlt":"Antenna drawing (identify the type)"},
  {"id":"D-061","section":6,"question":"The antenna shown is a:","correct":"Folded dipole","wrong":["Half-wave dipole","Quarter-wave ground plane","Yagi"],"explain":"A half-wave loop of two parallel conductors joined at the ends: a folded dipole (about 300 Ω).","image":"assets/questions/ant-folded.svg","imageAlt":"Antenna drawing (identify the type)"},
  {"id":"D-062","section":6,"question":"The antenna shown is a:","correct":"Quarter-wave ground plane","wrong":["Half-wave dipole","Folded dipole","Yagi"],"explain":"A λ/4 vertical with radials forming the ground plane (about 36 Ω, rising to ~50 Ω with drooping radials).","image":"assets/questions/ant-gp.svg","imageAlt":"Antenna drawing (identify the type)"},
  {"id":"D-063","section":6,"question":"The antenna shown is a:","correct":"Yagi","wrong":["Half-wave dipole","Folded dipole","Quarter-wave ground plane"],"explain":"A boom carrying a reflector, a driven element and directors: a Yagi beam.","image":"assets/questions/ant-yagi.svg","imageAlt":"Antenna drawing (identify the type)"},
  {"id":"D-064","section":6,"question":"The antenna shown is a:","correct":"End-fed wire","wrong":["Half-wave dipole","Folded dipole","Quarter-wave ground plane"],"explain":"A single wire fed at one end through a matching unit: an end-fed wire antenna.","image":"assets/questions/ant-endfed.svg","imageAlt":"Antenna drawing (identify the type)"},
  {"id":"D-065","section":6,"question":"The curve drawn above the half-wave dipole shown represents a quantity that is greatest at the centre and zero at the ends. That quantity is the:","correct":"Current","wrong":["Voltage","Feedline impedance","SWR"],"explain":"On a half-wave dipole, current is maximum at the centre feedpoint and zero at the ends. Voltage is the reverse.","image":"assets/questions/ant-dipole-dist.svg","imageAlt":"Dipole with a curve that peaks at the centre and falls to zero at the ends"},
  {"id":"P1-35","section":7,"question":"The wavelength of a 146 MHz signal is approximately:","correct":"2 m","wrong":["20 m","0.2 m","200 m"],"explain":"λ = 300 / f(MHz) = 300 / 146 ≈ 2.05 m. That's why it's called the 2 m band."},
  {"id":"P1-36","section":7,"question":"The polarisation of a radio wave is determined by:","correct":"The direction of its electric field relative to the Earth's surface","wrong":["The direction of its magnetic field relative to the Earth's surface","Its frequency","The height of the transmitting antenna"],"explain":"The electric field direction sets polarisation: vertical E-field = vertical polarisation."},
  {"id":"P1-37","section":7,"question":"Listed from lowest to highest altitude, the ionospheric layers are:","correct":"D, E, F1, F2","wrong":["F2, F1, E, D","E, D, F2, F1","D, F1, E, F2"],"explain":"D is lowest (about 60–90 km), then E, then F1 and F2 highest."},
  {"id":"P1-38","section":7,"question":"During daylight, the D layer:","correct":"Absorbs lower-frequency signals, and it disappears at night","wrong":["Refracts signals over the longest distances","Is present only at night","Reflects VHF signals"],"explain":"The D layer absorbs the lower frequencies by day and disappears after sunset."},
  {"id":"P1-39","section":7,"question":"The MUF for a path is 20 MHz. The optimum working frequency (OWF) is approximately:","correct":"17 MHz","wrong":["23 MHz","20 MHz","10 MHz"],"explain":"OWF is about 15% below MUF: 20 − (0.15 × 20) = 17 MHz."},
  {"id":"P2-35","section":7,"question":"The velocity of electromagnetic radiation in free space is approximately:","correct":"300 000 000 m/s","wrong":["300 000 m/s","3 000 m/s","343 m/s"],"explain":"300 million metres per second (3 × 10⁸ m/s)."},
  {"id":"P2-36","section":7,"question":"In an electromagnetic wave, the electric and magnetic fields are:","correct":"At right angles to each other and to the direction of travel","wrong":["Parallel to each other","Parallel to the direction of travel","Present only at night"],"explain":"E and H fields are perpendicular to each other and to the direction of propagation."},
  {"id":"P2-37","section":7,"question":"The maximum distance covered by a single F2-layer hop is about:","correct":"4 000 km","wrong":["400 km","40 km","40 000 km"],"explain":"The F2 layer gives the longest single refractions, about 4 000 km."},
  {"id":"P2-38","section":7,"question":"Ionisation of the ionosphere is caused mainly by:","correct":"Ultraviolet radiation and charged particles from the Sun","wrong":["The Moon's gravity","Lightning","Radio transmissions"],"explain":"Solar emissions (UV, X-rays and charged particles) ionise the upper atmosphere."},
  {"id":"P2-39","section":7,"question":"HF propagation conditions vary with a solar cycle of approximately:","correct":"11 years","wrong":["1 year","28 days","100 years"],"explain":"The sunspot cycle is about 11 years. Higher solar activity generally improves the higher HF bands."},
  {"id":"P3-35","section":7,"question":"A wavelength of 40 m corresponds to a frequency of:","correct":"7.5 MHz","wrong":["75 MHz","0.75 MHz","12 MHz"],"explain":"f(MHz) = 300 / λ(m) = 300 / 40 = 7.5 MHz."},
  {"id":"P3-36","section":7,"question":"A station is transmitting with a vertical antenna. For best reception, the receiving antenna should be:","correct":"Vertically polarised","wrong":["Horizontally polarised","Circularly polarised only","Pointed straight up"],"explain":"Transmit and receive antennas should use the same polarisation, which matters most at VHF/UHF."},
  {"id":"P3-37","section":7,"question":"Under free-space conditions, electromagnetic waves:","correct":"Travel in straight lines and spread out","wrong":["Follow the curve of the Earth","Travel in circles","Do not weaken with distance"],"explain":"In free space waves travel in straight lines and spread out, so field strength falls with distance."},
  {"id":"P3-38","section":7,"question":"At night, the F1 and F2 layers:","correct":"Combine into a single F layer","wrong":["Both disappear completely","Move below the D layer","Become the E layer"],"explain":"F1 and F2 are separate by day and combine into one F layer at night."},
  {"id":"P3-39","section":7,"question":"'Fading' (QSB) of a received HF signal refers to:","correct":"Variations in the strength of the received signal","wrong":["A permanent loss of the transmitter","The receiver's AGC failing","Changes in the transmitter's frequency"],"explain":"Fading is the rise and fall of received signal strength, often caused by multipath or ionospheric changes."},
  {"id":"X-26","section":7,"question":"The unit of frequency of an electromagnetic wave is the:","correct":"Hertz","wrong":["Metre","Watt","Henry"],"explain":"Frequency is measured in hertz (cycles per second)."},
  {"id":"X-27","section":7,"question":"Worldwide HF communication is possible mainly because of:","correct":"Multiple refractions (hops) between the ionosphere and the Earth","wrong":["Line-of-sight propagation","Repeaters on every continent","The D layer reflecting signals at night"],"explain":"Signals can hop several times between the ionosphere and the ground to reach around the world."},
  {"id":"X-28","section":7,"question":"Seasonal changes in the ionosphere affect:","correct":"Which frequency bands are most suitable for ionospheric communication","wrong":["Only VHF line-of-sight signals","The speed of light","The velocity factor of coax"],"explain":"Ionisation varies with the seasons, changing which HF bands work best."},
  {"id":"M-051","section":7,"question":"As frequency increases, wavelength:","correct":"Decreases","wrong":["Increases","Stays the same","Doubles"],"explain":"λ = c / f. Higher frequency means shorter wavelength."},
  {"id":"M-052","section":7,"question":"A horizontally polarised wave has its electric field:","correct":"Parallel to the Earth's surface","wrong":["Perpendicular to the Earth's surface","Rotating","In the direction of travel"],"explain":"Polarisation is set by the E-field. Horizontal E-field = horizontal polarisation."},
  {"id":"M-053","section":7,"question":"Using a horizontally polarised antenna to receive a vertically polarised VHF signal will usually result in:","correct":"A much weaker received signal","wrong":["A stronger signal","No difference","Doubling of the frequency"],"explain":"Cross-polarisation causes significant loss at VHF/UHF. Match the polarisation."},
  {"id":"M-054","section":7,"question":"VHF and UHF signals normally travel:","correct":"By line of sight, so range depends largely on antenna height and terrain","wrong":["Around the world by F2 refraction every day","Only at night","By D-layer reflection"],"explain":"VHF/UHF usually pass through the ionosphere, so coverage is mainly line of sight."},
  {"id":"M-055","section":7,"question":"The ionosphere is most strongly ionised:","correct":"During the day, especially at high solar activity","wrong":["At midnight","When there is no sunlight at all","Only in winter at night"],"explain":"Solar radiation causes ionisation, so it is strongest during daylight and solar maximum."},
  {"id":"M-056","section":7,"question":"The D layer is located at approximately:","correct":"60–90 km","wrong":["150–1 000 km","1 000–2 000 km","10–20 km"],"explain":"The D layer is the lowest layer, roughly 60–90 km above the Earth."},
  {"id":"M-057","section":7,"question":"The E layer lies:","correct":"Above the D layer and below the F layers","wrong":["Above the F2 layer","Below the D layer","At ground level"],"explain":"From the lowest up, the order is D, E, F1, F2."},
  {"id":"M-058","section":7,"question":"Signals on the lower HF bands (such as 80 m) travel much further at night mainly because:","correct":"The D layer disappears and stops absorbing them","wrong":["The F2 layer disappears","The Sun's UV increases","The E layer absorbs more"],"explain":"By day the D layer absorbs lower frequencies. At night it disappears, allowing skywave propagation."},
  {"id":"M-059","section":7,"question":"Frequencies above the MUF for a given path will:","correct":"Pass through the ionosphere instead of being refracted back to Earth","wrong":["Be absorbed by the D layer","Always reach the receiver","Be reflected by the ground only"],"explain":"Above the MUF the ionosphere cannot bend the signal back, so it escapes into space."},
  {"id":"M-060","section":7,"question":"The optimum working frequency is chosen below the MUF so that:","correct":"Communication is more reliable as ionospheric conditions vary","wrong":["The signal escapes into space","D-layer absorption is maximised","Polarisation is matched"],"explain":"Working about 15% below the MUF gives a margin for day-to-day variations."},
  {"id":"M-061","section":7,"question":"Long-distance HF communication over several thousand kilometres is mainly via the:","correct":"F2 layer","wrong":["D layer","Ground wave","Troposphere only"],"explain":"The F2 layer is highest and gives the longest single hops (about 4 000 km)."},
  {"id":"M-062","section":7,"question":"Around a solar maximum, the higher HF bands (such as 10 m):","correct":"Are more often open for long-distance contacts","wrong":["Are always closed","Are absorbed by the D layer","Only work at night"],"explain":"High solar activity raises the MUF, opening the higher HF bands more often."},
  {"id":"M-063","section":7,"question":"Fading caused by a signal arriving over two or more paths at once is called:","correct":"Multipath fading","wrong":["Polarisation matching","Harmonic distortion","Ground wave"],"explain":"Signals arriving by different paths add and cancel as conditions change, causing fading."},
  {"id":"M-064","section":7,"question":"QSB on an HF signal is best described as:","correct":"The signal strength rising and falling","wrong":["Interference from another station","Static crackles","A request to change frequency"],"explain":"QSB means 'your signals are fading'."},
  {"id":"M-065","section":7,"question":"An electromagnetic wave consists of:","correct":"Electric and magnetic fields","wrong":["Sound waves","Electric fields only","Magnetic fields only"],"explain":"EM waves have electric and magnetic fields at right angles to each other and to the direction of travel."},
  {"id":"M-066","section":7,"question":"Radio waves and light are both:","correct":"Electromagnetic radiation travelling at about 300 000 km/s in free space","wrong":["Sound waves","Charged particles from the Sun","Types of ionospheric layer"],"explain":"They differ only in frequency. Both travel at the speed of light."},
  {"id":"M-067","section":7,"question":"Compared with a summer daytime, the MUF on a winter night is generally:","correct":"Lower, so lower HF bands are favoured","wrong":["Higher, so the highest bands open","The same","Zero"],"explain":"Less ionisation at night (and in winter) lowers the MUF, favouring lower frequencies."},
  {"id":"G-116","section":7,"question":"The wavelength of a 3.5 MHz signal is approximately:","correct":"85.7 m","wrong":["857.1 m","8.6 m","171.4 m"],"explain":"λ = 300 / f(MHz) = 300 / 3.5 ≈ 85.7 m."},
  {"id":"G-117","section":7,"question":"The wavelength of a 10.1 MHz signal is approximately:","correct":"29.7 m","wrong":["297 m","3 m","59.4 m"],"explain":"λ = 300 / f(MHz) = 300 / 10.1 ≈ 29.7 m."},
  {"id":"G-118","section":7,"question":"The wavelength of a 18.1 MHz signal is approximately:","correct":"16.6 m","wrong":["165.7 m","1.7 m","33.1 m"],"explain":"λ = 300 / f(MHz) = 300 / 18.1 ≈ 16.6 m."},
  {"id":"G-119","section":7,"question":"The wavelength of a 24.9 MHz signal is approximately:","correct":"12 m","wrong":["120.5 m","1.2 m","24.1 m"],"explain":"λ = 300 / f(MHz) = 300 / 24.9 ≈ 12 m."},
  {"id":"G-120","section":7,"question":"The wavelength of a 432 MHz signal is approximately:","correct":"69.4 cm","wrong":["6.9 m","6.9 cm","1.4 m"],"explain":"λ = 300 / f(MHz) = 300 / 432 ≈ 69.4 cm."},
  {"id":"G-121","section":7,"question":"The wavelength of a 1 296 MHz signal is approximately:","correct":"23.1 cm","wrong":["2.3 m","2.3 cm","46.3 cm"],"explain":"λ = 300 / f(MHz) = 300 / 1 296 ≈ 23.1 cm."},
  {"id":"G-122","section":7,"question":"A wavelength of 80 m corresponds to a frequency of approximately:","correct":"3.75 MHz","wrong":["37.5 MHz","0.375 MHz","7.5 MHz"],"explain":"f(MHz) = 300 / λ(m) = 300 / 80 = 3.75 MHz."},
  {"id":"G-123","section":7,"question":"A wavelength of 20 m corresponds to a frequency of approximately:","correct":"15 MHz","wrong":["150 MHz","1.5 MHz","30 MHz"],"explain":"f(MHz) = 300 / λ(m) = 300 / 20 = 15 MHz."},
  {"id":"G-124","section":7,"question":"A wavelength of 15 m corresponds to a frequency of approximately:","correct":"20 MHz","wrong":["200 MHz","2 MHz","40 MHz"],"explain":"f(MHz) = 300 / λ(m) = 300 / 15 = 20 MHz."},
  {"id":"G-125","section":7,"question":"A wavelength of 6 m corresponds to a frequency of approximately:","correct":"50 MHz","wrong":["500 MHz","5 MHz","100 MHz"],"explain":"f(MHz) = 300 / λ(m) = 300 / 6 = 50 MHz."},
  {"id":"G-126","section":7,"question":"The MUF for a path is 10 MHz. The optimum working frequency is approximately:","correct":"8.5 MHz","wrong":["11.5 MHz","10 MHz","5 MHz"],"explain":"OWF ≈ MUF − 15% = 10 × 0.85 = 8.5 MHz."},
  {"id":"G-127","section":7,"question":"The MUF for a path is 30 MHz. The optimum working frequency is approximately:","correct":"25.5 MHz","wrong":["34.5 MHz","30 MHz","15 MHz"],"explain":"OWF ≈ MUF − 15% = 30 × 0.85 = 25.5 MHz."},
  {"id":"G-128","section":7,"question":"The MUF for a path is 24 MHz. The optimum working frequency is approximately:","correct":"20.4 MHz","wrong":["27.6 MHz","24 MHz","12 MHz"],"explain":"OWF ≈ MUF − 15% = 24 × 0.85 = 20.4 MHz."},
  {"id":"D-066","section":7,"question":"The daytime ionosphere is shown with its layers labelled. The layer marked X is the:","correct":"F1 layer","wrong":["D layer","E layer","F2 layer"],"explain":"From the ground up, the layers are D, E, F1 and F2. X sits between E and F2, so it is F1.","image":"assets/questions/iono-layers.svg","imageAlt":"Daytime ionosphere layers from ground up: D, E, X, F2"},
  {"id":"P1-40","section":8,"question":"The intermediate frequency (IF) typically used in FM broadcast receivers is:","correct":"10.7 MHz","wrong":["455 kHz","88 MHz","36 MHz"],"explain":"FM broadcast receivers typically use a 10.7 MHz IF. AM broadcast receivers typically use 455 kHz."},
  {"id":"P1-41","section":8,"question":"TV masthead and distribution amplifiers are prone to amateur interference because they:","correct":"Are wide-band devices that are easily overloaded by strong signals","wrong":["Only amplify the amateur bands","Have very narrow bandwidth","Contain no active components"],"explain":"They amplify a wide range of frequencies and overload easily when a strong nearby signal is present."},
  {"id":"P1-42","section":8,"question":"To reduce interference from an HF amateur transmitter to a nearby TV, the filter fitted at the TV antenna input should be a:","correct":"High-pass filter","wrong":["Low-pass filter","Band-stop filter tuned to TV channels","Audio filter"],"explain":"A high-pass filter passes TV frequencies (above 50 MHz) and blocks the lower HF amateur signals."},
  {"id":"P1-43","section":8,"question":"Ferrite toroids or beads fitted to speaker leads help reduce interference by:","correct":"Choking off RF currents picked up on the leads before they reach the audio amplifier","wrong":["Increasing the audio volume","Shielding the speaker from magnetic fields","Changing the speaker's impedance"],"explain":"Ferrites act as RF chokes on the leads, blocking RF while letting audio pass."},
  {"id":"P1-44","section":8,"question":"A neighbour complains that your transmissions interfere with their TV. The best first step is to:","correct":"Respond politely, check your own station is operating correctly and offer help to find the cause","wrong":["Ignore the complaint because amateurs have priority","Tell them to contact the police","Immediately increase power to prove the TV is faulty"],"explain":"Diplomacy first. Check your own station and work together. Advice is available from your club/WIA, and the ACMA has a role if needed."},
  {"id":"P2-40","section":8,"question":"The intermediate frequency typically used in AM broadcast receivers is:","correct":"455 kHz","wrong":["10.7 MHz","1 606 kHz","36 MHz"],"explain":"AM broadcast receivers typically use a 455 kHz IF. FM broadcast receivers typically use 10.7 MHz."},
  {"id":"P2-41","section":8,"question":"An overloaded audio amplifier can cause interference because its non-linearity:","correct":"Demodulates (rectifies) the RF signal so it is heard in the audio","wrong":["Amplifies only the wanted audio","Reduces the RF signal","Changes the amateur's transmit frequency"],"explain":"Non-linear stages act like a detector and recover the modulation from strong RF."},
  {"id":"P2-42","section":8,"question":"To reduce harmonic radiation from an HF transmitter, the filter fitted at the transmitter output should be a:","correct":"Low-pass filter","wrong":["High-pass filter","Audio filter","Mains filter on the neutral only"],"explain":"Harmonics are above the operating frequency. A low-pass filter passes the wanted signal and attenuates them."},
  {"id":"P2-43","section":8,"question":"Compared with unbalanced antennas, balanced antenna systems tend to:","correct":"Cause fewer EMC problems","wrong":["Cause more EMC problems","Always need an ATU","Only work on VHF"],"explain":"Balanced antennas (e.g. a balun-fed dipole) cause fewer EMC problems."},
  {"id":"P2-44","section":8,"question":"A suitable precaution to reduce EMC problems when installing a transceiver in a vehicle is to:","correct":"Run the power leads directly to the battery and route the coax away from the engine management unit and its wiring","wrong":["Connect power to any convenient wire under the dash","Mount the antenna inside the engine bay","Run the coax alongside the ECU wiring loom"],"explain":"Direct battery connection, good bonding and keeping RF away from vehicle electronics reduce interference."},
  {"id":"P3-40","section":8,"question":"Which amateur band falls within the VHF television RF range of 50–225 MHz?","correct":"2 m (144–148 MHz)","wrong":["20 m (14 MHz)","70 cm (430–450 MHz)","80 m (3.5 MHz)"],"explain":"144–148 MHz lies inside the 50–225 MHz VHF TV range (as does 6 m at 50–54 MHz)."},
  {"id":"P3-41","section":8,"question":"Amateur signals often enter the audio stages of a home stereo system via:","correct":"Long speaker leads and other interconnecting cables acting as antennas","wrong":["The mains fuse","The speaker cones directly","The volume control knob"],"explain":"Long leads pick up RF and feed it into audio stages, where it can be detected."},
  {"id":"P3-42","section":8,"question":"A band-stop (notch) filter would typically be used to:","correct":"Reject one strong interfering frequency while passing the others","wrong":["Pass only a narrow band of frequencies","Pass only frequencies above a cut-off","Pass only frequencies below a cut-off"],"explain":"Band-stop rejects a band and passes the rest. Band-pass is the opposite."},
  {"id":"P3-43","section":8,"question":"A filter that passes all frequencies above a cut-off frequency and attenuates those below it is a:","correct":"High-pass filter","wrong":["Low-pass filter","Band-pass filter","Band-stop filter"],"explain":"High-pass = passes the highs. Its response curve rises at the cut-off frequency."},
  {"id":"P3-44","section":8,"question":"Good radio practice to minimise EMC problems is to:","correct":"Use the minimum transmitter power needed for effective communication","wrong":["Always use maximum power","Run the feedline parallel to the antenna","Use unbalanced antennas close to the house"],"explain":"Reducing field strength to the minimum needed is good practice. The feedline should also leave the antenna at right angles."},
  {"id":"X-29","section":8,"question":"The intermediate frequency range used in television receivers is approximately:","correct":"33–40 MHz","wrong":["455 kHz","10.7 MHz","470–854 MHz"],"explain":"TV IF is about 33–40 MHz. 470–854 MHz is the UHF TV RF range."},
  {"id":"X-30","section":8,"question":"The AM broadcast band covers approximately:","correct":"525–1 606 kHz","wrong":["88–108 MHz","50–225 MHz","33–40 MHz"],"explain":"AM broadcast is 525–1 606 kHz. FM broadcast is 88–108 MHz."},
  {"id":"X-31","section":8,"question":"To minimise EMC problems, the feedline should leave the antenna:","correct":"At right angles to the antenna","wrong":["Parallel to one leg of the antenna","Coiled up tightly","Along the house wiring"],"explain":"Leaving at right angles reduces coupling between the antenna and the feedline."},
  {"id":"X-32","section":8,"question":"Most television and broadcast radio receivers use:","correct":"Superheterodyne circuits","wrong":["Crystal sets","Direct-conversion transmitters","Spark-gap detectors"],"explain":"Most use superhets, so amateur signals can enter via the RF or IF stages."},
  {"id":"X-33","section":8,"question":"A band-pass filter fitted in front of a receiver will:","correct":"Pass a chosen band and reject strong signals outside it","wrong":["Pass all frequencies above a cut-off","Reject one single frequency only","Increase receiver gain on all bands"],"explain":"Band-pass filters pass only the wanted band, improving immunity to strong out-of-band signals."},
  {"id":"M-068","section":8,"question":"Electromagnetic compatibility (EMC) is the ability of equipment to:","correct":"Work properly in its electromagnetic environment without causing or suffering unacceptable interference","wrong":["Transmit at maximum power","Receive only amateur signals","Operate without a power supply"],"explain":"EMC covers both immunity to interference and not generating interference."},
  {"id":"M-069","section":8,"question":"Amateur signals can enter a TV or radio receiver through its:","correct":"RF or IF stages","wrong":["Remote control only","Screen glass","Loudspeaker cone"],"explain":"The syllabus notes entry via RF or IF stages, and via audio stages through long leads."},
  {"id":"M-070","section":8,"question":"The second harmonic of a 28 MHz transmitter falls at 56 MHz. This could interfere with:","correct":"VHF services, including the low VHF television range","wrong":["AM broadcast radio only","Only other 10 m stations","Nothing, because harmonics cannot radiate"],"explain":"56 MHz is within the 50–225 MHz VHF TV range noted in the syllabus. A low-pass filter at the transmitter helps."},
  {"id":"M-071","section":8,"question":"Interference that is heard on all channels of a TV or radio, regardless of tuning, usually indicates:","correct":"Overload or pick-up in the affected equipment rather than a transmitter fault","wrong":["A harmonic falling on one channel","The amateur is off frequency","Weather effects only"],"explain":"Interference that is not tuning-dependent points to overload or audio pick-up in the victim device. Filtering there is needed."},
  {"id":"M-072","section":8,"question":"Interference that appears on only one TV channel at a harmonic of your transmit frequency suggests:","correct":"Harmonic radiation from the transmitter, needing a low-pass filter at the transmitter","wrong":["Overload of the TV's audio amplifier","Feedline polarisation","A faulty TV remote"],"explain":"A specific channel matching a harmonic points to the transmitter. Filter at the source."},
  {"id":"M-073","section":8,"question":"A low-pass filter at the transmitter will NOT cure interference caused by:","correct":"Overload of the neighbour's TV by the strong fundamental signal","wrong":["Harmonics of the transmitter","Spurious emissions above the operating frequency","Parasitic oscillations above the operating frequency"],"explain":"Fundamental overload must be fixed at the victim device, with a high-pass filter, band-stop filter or ferrite."},
  {"id":"M-074","section":8,"question":"A masthead amplifier overloaded by an amateur signal is best treated by:","correct":"Fitting a suitable filter before the amplifier input","wrong":["Increasing the amplifier's gain","Removing the TV antenna","Increasing transmitter power"],"explain":"A filter (such as high-pass or band-stop) ahead of the wideband amplifier keeps the strong signal out."},
  {"id":"M-075","section":8,"question":"An audio amplifier picking up RF can be helped by:","correct":"Ferrite chokes on speaker and input leads, and small bypass capacitors","wrong":["Longer speaker leads","Removing the earth connection","Turning the volume to maximum"],"explain":"Ferrite chokes and bypassing stop RF reaching non-linear stages, where it would be demodulated."},
  {"id":"M-076","section":8,"question":"Winding several turns of a cable through a ferrite toroid creates:","correct":"An RF choke that blocks common-mode RF currents on the cable","wrong":["A capacitor","An antenna","A rectifier"],"explain":"Ferrites add impedance to RF on the cable while normal signals pass."},
  {"id":"M-077","section":8,"question":"A high-pass filter for TV interference is normally fitted:","correct":"At the TV antenna input","wrong":["At the transmitter output","In the mains plug","On the microphone lead"],"explain":"It lets TV frequencies through and blocks lower-frequency HF amateur signals at the victim set."},
  {"id":"M-078","section":8,"question":"A typical use of a low-pass filter in an amateur station is:","correct":"At the HF transmitter output to reduce harmonics","wrong":["At the TV antenna input to block HF","In the speaker leads to block audio","To pass only VHF signals"],"explain":"Low-pass filters pass the HF transmit signal and attenuate VHF harmonics."},
  {"id":"M-079","section":8,"question":"A typical use of a band-pass filter in an amateur station is to:","correct":"Allow only one amateur band through to or from the radio","wrong":["Pass everything above 50 MHz","Remove mains hum","Pass only DC"],"explain":"Band-pass filters help multi-station setups (such as contests) and reduce out-of-band signals."},
  {"id":"M-080","section":8,"question":"Unbalanced antennas fed without a balun are more likely to cause EMC problems because:","correct":"RF current can flow on the outside of the coax and radiate inside the house","wrong":["They radiate less power","They have no feedline","They are always horizontally polarised"],"explain":"Common-mode current on the feedline puts RF close to household electronics."},
  {"id":"M-081","section":8,"question":"To minimise EMC problems, antennas should be located:","correct":"As far as practical from the house and neighbouring electronics","wrong":["Inside the roof space next to the TV antenna","Along the house mains wiring","Close to the neighbour's TV antenna"],"explain":"Distance reduces field strength at nearby equipment."},
  {"id":"M-082","section":8,"question":"Using a transceiver in a modern vehicle without precautions could:","correct":"Interfere with engine management and other electronic systems","wrong":["Improve fuel economy","Charge the battery","Have no effect at all"],"explain":"Strong RF can upset vehicle electronics. Follow the manufacturer's advice."},
  {"id":"M-083","section":8,"question":"Before installing a transceiver in a vehicle, it is wise to:","correct":"Check the vehicle manufacturer's guidelines for fitting radio equipment","wrong":["Mount the antenna on the engine block","Connect power to the airbag circuit","Run the coax through the engine management loom"],"explain":"Manufacturers often specify antenna locations, power connections and maximum power."},
  {"id":"M-084","section":8,"question":"A good antenna position on a vehicle for minimising EMC is usually:","correct":"On the roof, away from vehicle electronics","wrong":["Inside the dashboard","Next to the engine computer","Under the seat"],"explain":"A roof mount gives a good ground plane and keeps RF away from the electronics."},
  {"id":"M-085","section":8,"question":"EMC problems with neighbours have the potential to:","correct":"Cause neighbourhood disputes, so diplomacy is important","wrong":["Always be ignored legally","Be solved only by increasing power","Be fixed only by the neighbour"],"explain":"Handle complaints calmly and cooperatively. Clubs, the WIA and the ACMA can offer advice."},
  {"id":"M-086","section":8,"question":"A good source of help and advice on resolving interference to a neighbour's equipment is:","correct":"Your radio club, the WIA or the ACMA","wrong":["Social media arguments","The neighbour's insurance company","Nobody; it cannot be fixed"],"explain":"Clubs and the WIA have experienced members. The ACMA provides information and can investigate."},
  {"id":"M-087","section":8,"question":"The role of the ACMA in interference matters includes:","correct":"Providing information and investigating interference when required","wrong":["Selling filters","Repairing TVs","Issuing fines to neighbours for owning TVs"],"explain":"The ACMA manages the spectrum and can investigate interference."},
  {"id":"M-088","section":8,"question":"Before blaming a neighbour's equipment, you should check that your own station:","correct":"Is correctly adjusted, filtered, and not over-driven or over-modulated","wrong":["Is running maximum power","Has its earth removed","Uses the longest possible feedline"],"explain":"Start by confirming your own station is clean. Then work on the affected equipment."},
  {"id":"M-089","section":8,"question":"Reducing transmitter power to the minimum needed helps EMC because it:","correct":"Reduces the field strength reaching nearby equipment","wrong":["Increases harmonics","Changes the operating band","Removes the need for filters"],"explain":"Lower field strength means less chance of overload or pick-up."},
  {"id":"M-090","section":8,"question":"A home stereo picks up your SSB voice only when you transmit, whatever station it is tuned to. The most likely cause is:","correct":"RF being rectified in the audio stages (audio rectification)","wrong":["A harmonic on the broadcast frequency","Your transmitter is on the wrong band","The stereo's tuner is faulty"],"explain":"Hearing your voice whatever the tuning shows the RF is entering the audio circuits. Fit ferrites and bypassing."},
  {"id":"M-091","section":8,"question":"FM broadcast receivers operate in the range:","correct":"88–108 MHz","wrong":["525–1 606 kHz","470–854 MHz","33–40 MHz"],"explain":"FM broadcast is 88–108 MHz, with a typical IF of 10.7 MHz."},
  {"id":"M-092","section":8,"question":"UHF television receivers operate in the RF range of approximately:","correct":"470–854 MHz","wrong":["50–225 MHz","88–108 MHz","33–40 MHz"],"explain":"The syllabus gives 470–854 MHz for UHF TV RF."},
  {"id":"D-047","section":8,"question":"The response curve shown is that of a:","correct":"Low-pass filter","wrong":["High-pass filter","Band-pass filter","Band-stop (notch) filter"],"explain":"Passes frequencies below the cut-off and attenuates those above. It is used at a transmitter output to reduce harmonics.","image":"assets/questions/filt-lp.svg","imageAlt":"Graph of filter output against frequency"},
  {"id":"D-048","section":8,"question":"The response curve shown is that of a:","correct":"High-pass filter","wrong":["Low-pass filter","Band-pass filter","Band-stop (notch) filter"],"explain":"Passes frequencies above the cut-off and attenuates those below. It is used at a TV input to block HF signals.","image":"assets/questions/filt-hp.svg","imageAlt":"Graph of filter output against frequency"},
  {"id":"D-049","section":8,"question":"The response curve shown is that of a:","correct":"Band-pass filter","wrong":["Low-pass filter","High-pass filter","Band-stop (notch) filter"],"explain":"Passes a band of frequencies and attenuates those either side.","image":"assets/questions/filt-bp.svg","imageAlt":"Graph of filter output against frequency"},
  {"id":"D-050","section":8,"question":"The response curve shown is that of a:","correct":"Band-stop (notch) filter","wrong":["Low-pass filter","High-pass filter","Band-pass filter"],"explain":"Attenuates a narrow band and passes everything else. It is used to notch out one interfering signal.","image":"assets/questions/filt-bs.svg","imageAlt":"Graph of filter output against frequency"},
  {"id":"P1-45","section":10,"question":"The first action to take in an accident involving electricity is to:","correct":"Safely switch off the power","wrong":["Pull the person away with your hands","Start CPR immediately","Pour water on the person"],"explain":"Switch off the power first. Never touch the casualty until the power is off."},
  {"id":"P1-46","section":10,"question":"Lead-acid batteries can be dangerous because they:","correct":"Contain chemicals, give off fumes and may explode if exposed to sparks or flames","wrong":["Produce strong RF radiation","Contain no hazardous materials","Can only be charged outdoors"],"explain":"Batteries contain corrosive chemicals and emit gases (e.g. hydrogen) that can explode with a spark or flame."},
  {"id":"P1-47","section":10,"question":"The safe distance from a transmitting antenna depends on:","correct":"The ERP, operating frequency, antenna type and orientation","wrong":["Only the length of the coax","The colour of the antenna","Only the time of day"],"explain":"The syllabus lists ERP, frequency, antenna type and orientation."},
  {"id":"P1-48","section":10,"question":"When a thunderstorm is approaching, good practice is to:","correct":"Stop operating and disconnect the antennas from your equipment","wrong":["Continue operating with reduced power","Operate only on VHF","Connect the antenna directly to mains earth"],"explain":"Disconnect antennas from equipment before a storm and never operate during one."},
  {"id":"P2-45","section":10,"question":"A person is in contact with a live electrical conductor. You should:","correct":"Not touch them until the power has been switched off","wrong":["Grab them by the arm and pull them clear","Throw water over them","Start CPR while they are still in contact"],"explain":"Touching the casualty while the power is on can make you a second casualty. Switch off first, then call 000 and give CPR if needed."},
  {"id":"P2-46","section":10,"question":"Mains-operated equipment that is sold, hired or supplied in Australia must:","correct":"Be approved by an electrical safety authority and carry an approval label","wrong":["Be home-made","Have no fuse","Be double-switched in the earth lead"],"explain":"Mains equipment must be approved and labelled."},
  {"id":"P2-47","section":10,"question":"When replacing a blown fuse, you should:","correct":"Find the cause first, then fit a fuse of the rating specified by the manufacturer","wrong":["Fit a higher-rated fuse so it does not blow again","Replace it with a piece of wire","Fit any fuse that physically fits"],"explain":"Always use the correct rating. A higher rating may allow overheating and fire."},
  {"id":"P2-48","section":10,"question":"Antennas and their fittings must:","correct":"Never be connected to, or sited close to, mains poles and power lines","wrong":["Be attached to power poles for extra height","Be installed only during wet weather","Be mounted touching power lines to improve earthing"],"explain":"Contact with power lines can be fatal. Antennas must be secured well clear of them."},
  {"id":"P3-45","section":10,"question":"A power lead is frayed or damaged. It should be:","correct":"Replaced, or repaired by an authorised person","wrong":["Wrapped in tape and used as normal","Used only for low-power equipment","Ignored if the equipment still works"],"explain":"Damaged leads are a shock and fire risk. Replace them or have them repaired by an authorised person."},
  {"id":"P3-46","section":10,"question":"A clearly marked switch to turn off all station equipment is desirable because:","correct":"It lets anyone quickly cut the power in an emergency","wrong":["It reduces SWR","It improves receiver sensitivity","It is required to change bands"],"explain":"In an emergency (e.g. electric shock or fire) power can be cut quickly by anyone."},
  {"id":"P3-47","section":10,"question":"The danger from electromagnetic radiation (EMR) varies with:","correct":"Frequency, power and proximity to the antenna","wrong":["Only the colour of the antenna","Only the type of microphone","The time of day only"],"explain":"Higher power, closer distance and some frequencies increase the risk."},
  {"id":"P3-48","section":10,"question":"An operable amateur station should be:","correct":"Secured so it is not accessible to unauthorised persons","wrong":["Left switched on for anyone to use","Located only outdoors","Operated only by children under supervision"],"explain":"The syllabus requires that an operable station must not be accessible to unauthorised persons."},
  {"id":"X-34","section":10,"question":"Once the power has been switched off at an electric shock incident, you should:","correct":"Call emergency services (000) immediately and give CPR if needed","wrong":["Wait to see if the person recovers by themselves","Drive the person to hospital before calling anyone","Restore power to check the equipment"],"explain":"Call 000 straight away. CPR may be needed."},
  {"id":"X-35","section":10,"question":"Listening with headphones at excessive volume can:","correct":"Damage your hearing","wrong":["Improve receiver selectivity","Reduce RF exposure","Cause harmonics"],"explain":"Prolonged loud audio can cause permanent hearing damage."},
  {"id":"X-36","section":10,"question":"Erecting an antenna tower or mast should be done:","correct":"By suitably qualified persons, because it is potentially dangerous","wrong":["By one person working alone","Only in windy weather","Near power lines for support"],"explain":"Antenna erection is hazardous (falls, collapse, power lines) and should be done by suitably qualified persons."},
  {"id":"X-37","section":10,"question":"The purpose of a fuse is to:","correct":"Prevent excessive current that may cause heat damage or fire","wrong":["Increase the supply voltage","Filter RF from the mains","Improve the earth connection"],"explain":"A fuse melts and breaks the circuit when the current is too high."},
  {"id":"X-38","section":10,"question":"Before wiring or testing mains-operated equipment, an unqualified person should:","correct":"Check the relevant state electrical authority requirements","wrong":["Go ahead if the equipment is low power","Remove the earth wire first","Work on it while it is plugged in to test it"],"explain":"Rules about unqualified people working on mains leads, plugs and equipment vary. Check the state requirements."},
  {"id":"X-39","section":10,"question":"People and animals should be kept:","correct":"A safe distance away from transmitting antennas","wrong":["As close as possible to antennas to check them","Only away from receiving antennas","Near antennas only on HF"],"explain":"RF exposure risk rises with power and proximity, so keep people and animals at a safe distance."},
  {"id":"M-093","section":10,"question":"High voltages and high currents are:","correct":"Dangerous and potentially lethal","wrong":["Safe if the equipment is switched on","Only dangerous above 10 kV","Only dangerous in wet weather"],"explain":"Both high voltages and high currents can kill or cause serious burns and fires."},
  {"id":"M-094","section":10,"question":"Even a 13.8 V DC supply can be dangerous because:","correct":"It can deliver very high currents that cause burns, fires and melted wiring","wrong":["Its voltage is lethal to touch","It produces RF radiation","It cannot be fused"],"explain":"High-current low-voltage supplies (and batteries) can heat wires and tools very quickly. Fuse power leads."},
  {"id":"M-095","section":10,"question":"Large or high-voltage capacitors are dangerous because they:","correct":"Can store a charge after the power is switched off","wrong":["Always explode when switched on","Produce RF radiation","Cannot be discharged"],"explain":"Stored charge can give a severe shock. Allow bleed time or discharge them safely before working on equipment."},
  {"id":"M-096","section":10,"question":"Most mains-powered radio equipment has a safety earth connection so that:","correct":"A fault to the metal case blows the fuse rather than making the case live","wrong":["Receive noise is increased","The equipment uses less power","The antenna works better"],"explain":"The safety earth gives fault current a path, operating the protection and preventing shock."},
  {"id":"M-097","section":10,"question":"The safety earth wire in equipment should:","correct":"Never be removed or disconnected","wrong":["Be removed to reduce hum","Be connected to the neutral","Be used as the antenna radial"],"explain":"Removing the safety earth defeats the protection and can make the case live during a fault."},
  {"id":"M-098","section":10,"question":"Mains equipment approved for sale will carry:","correct":"An approval label or marking","wrong":["A hand-written note","No markings at all","A WIA sticker"],"explain":"Approved electrical equipment carries an approval or regulatory compliance mark."},
  {"id":"M-099","section":10,"question":"Fitting a fuse rated much higher than specified is dangerous because:","correct":"A fault could overheat wiring or start a fire before the fuse blows","wrong":["The equipment will not turn on","It reduces RF output","It increases the voltage"],"explain":"Always fit the rating specified by the manufacturer or supply authority."},
  {"id":"M-100","section":10,"question":"Before replacing a fuse in mains-powered equipment, you should:","correct":"Switch off and unplug the equipment","wrong":["Leave it plugged in to test it","Remove the earth wire","Increase the supply voltage"],"explain":"Isolate the supply first, then fit the correct fuse."},
  {"id":"M-101","section":10,"question":"Cables trailing across the floor of a radio shack are:","correct":"Trip hazards that can also damage equipment and connections","wrong":["Acceptable if they are coax","Good for earthing","Required for RF safety"],"explain":"Plan the station layout so leads are secured and out of walkways."},
  {"id":"M-102","section":10,"question":"A well-laid-out station should allow:","correct":"Easy access to a clearly marked switch that turns off all equipment","wrong":["Equipment stacked loosely on the floor","Live terminals left exposed","Power boards daisy-chained together"],"explain":"A clearly marked master switch lets anyone isolate the station quickly."},
  {"id":"M-103","section":10,"question":"A power board shows signs of overheating. You should:","correct":"Stop using it and have the load and board checked","wrong":["Cover it to hide it","Plug more equipment into it","Spray water on it"],"explain":"Overheating points to overload or a fault and is a fire risk."},
  {"id":"M-104","section":10,"question":"CPR may be needed after an electric shock because:","correct":"The shock can stop the casualty's heart or breathing","wrong":["It prevents burns","It discharges static","It earths the casualty"],"explain":"Call 000 and give CPR if the casualty is not breathing normally, once the power is off."},
  {"id":"M-105","section":10,"question":"Lead-acid batteries should be charged in a well-ventilated area because:","correct":"They can give off explosive hydrogen gas","wrong":["They need cooling air to work at all","Ventilation increases the voltage","It reduces RF interference"],"explain":"Hydrogen can build up and explode if ignited by a spark."},
  {"id":"M-106","section":10,"question":"A lithium battery pack that is swollen or damaged should:","correct":"Not be used, and should be disposed of safely","wrong":["Be charged quickly to fix it","Be punctured to release pressure","Be stored next to the charger"],"explain":"Damaged batteries can catch fire or explode. Never puncture or keep charging them."},
  {"id":"M-107","section":10,"question":"Short-circuiting the terminals of a car battery with a spanner can:","correct":"Cause sparks, severe burns, and possibly a battery explosion","wrong":["Safely discharge it","Recharge it faster","Improve its capacity"],"explain":"Batteries can deliver huge currents. Insulate tools and remove metal jewellery."},
  {"id":"M-108","section":10,"question":"Exposure to RF electromagnetic radiation is generally greatest:","correct":"Close to a transmitting antenna running high power","wrong":["Far from any antenna","When the transmitter is switched off","Near a receiving-only antenna"],"explain":"Field strength falls with distance, so the risk is highest close to high-power antennas."},
  {"id":"M-109","section":10,"question":"A handheld VHF transceiver should be operated:","correct":"With the antenna held away from the eyes and face","wrong":["With the antenna touching the eye","With the antenna removed","Inside a closed metal box"],"explain":"Keep antennas away from the body and especially the eyes. Exposure depends on proximity."},
  {"id":"M-110","section":10,"question":"Antennas should be installed so that people cannot:","correct":"Touch them or come too close while they are transmitting","wrong":["See them","Hear the station","Use the garden"],"explain":"Keep antennas out of reach and at a safe distance from where people and animals go."},
  {"id":"M-111","section":10,"question":"When working on a roof or tower to install an antenna, you should:","correct":"Use proper fall protection and not work alone","wrong":["Work alone at night","Work in high winds","Lean the mast against the power line"],"explain":"Antenna work is hazardous. Use safe practices, have help, and check for overhead power lines."},
  {"id":"M-112","section":10,"question":"Lightning protection on an outdoor antenna installation is:","correct":"Good practice, as is disconnecting antennas from equipment before storms","wrong":["Unnecessary for amateurs","Achieved by turning the radio off only","Provided by the coax shield alone"],"explain":"Use lightning arrestors and earthing, and disconnect the antenna when storms are near."},
  {"id":"M-113","section":10,"question":"Before raising a mast, the first thing to check is:","correct":"That no power lines are nearby that it could contact if it falls","wrong":["The SWR","The band conditions","The colour of the mast"],"explain":"Contact with power lines can be fatal. Site masts so they cannot reach them even if they fall."},
  {"id":"M-114","section":10,"question":"Unauthorised people (such as children) using your station unsupervised should be prevented by:","correct":"Securing the station, for example by locking the room or disabling the equipment","wrong":["Leaving the radio on","Hiding the microphone in plain sight","Turning up the volume"],"explain":"An operable station must not be accessible to unauthorised persons."},
  {"id":"P1-49","section":11,"question":"To measure current with a multimeter, the meter must be connected:","correct":"In series with the circuit","wrong":["In parallel across the supply","Across the load","Between the circuit and earth only"],"explain":"Current must flow through the meter, so it goes in series. Voltage is measured in parallel."},
  {"id":"P1-50","section":11,"question":"A crystal calibrator is used to:","correct":"Provide marker signals at known frequency intervals for checking a receiver's dial calibration","wrong":["Measure transmitter output power","Measure SWR","Measure the resistance of an antenna"],"explain":"A crystal calibrator gives accurate markers (e.g. every 100 kHz). Its accuracy depends on the crystal."},
  {"id":"P2-49","section":11,"question":"Transmitter RF output power should be measured with:","correct":"A suitably calibrated RF power meter, normally into a dummy load","wrong":["A multimeter on the AC volts range","A frequency counter","An ohmmeter"],"explain":"Use a calibrated RF wattmeter. A dummy load avoids radiating while testing."},
  {"id":"P2-50","section":11,"question":"A limitation of a digital frequency counter is that:","correct":"Its accuracy depends on the accuracy of its internal reference (timebase) oscillator","wrong":["It can only measure audio frequencies","It measures power, not frequency","It never needs calibration"],"explain":"A counter is only as accurate as its reference. It also needs enough signal to count reliably."},
  {"id":"P3-49","section":11,"question":"Before measuring resistance with a multimeter, you should:","correct":"Switch off and disconnect power from the circuit","wrong":["Connect the meter in series with the supply","Set the meter to the AC volts range","Make sure the circuit is powered on"],"explain":"Ohmmeters use their own battery. Measuring a live circuit gives wrong readings and can damage the meter."},
  {"id":"P3-50","section":11,"question":"Standard frequency and time transmissions can be used to:","correct":"Check the calibration of frequency-measuring equipment against an accurate reference","wrong":["Measure the SWR of an antenna","Measure transmitter power","Replace a dummy load"],"explain":"They broadcast very accurate frequencies that can be used as a reference for checking calibration."},
  {"id":"X-40","section":11,"question":"To measure voltage across a component with a multimeter, the meter is connected:","correct":"In parallel across the component","wrong":["In series with the component","Between the component and earth only","With the circuit switched off"],"explain":"Voltage is measured across (in parallel). Current is measured in series."},
  {"id":"X-41","section":11,"question":"Checking SWR frequently is good practice because it helps:","correct":"Avoid transmitter damage and potential interference","wrong":["Increase receiver sensitivity","Measure frequency accurately","Reduce the battery current"],"explain":"A sudden high SWR warns of a fault that could damage the transmitter or cause interference."},
  {"id":"X-42","section":11,"question":"When measuring an unknown voltage with a multimeter, you should first select:","correct":"The highest voltage range, then switch down","wrong":["The lowest voltage range","The resistance range","The current range"],"explain":"Starting high protects the meter. Switch down for a more precise reading."},
  {"id":"M-115","section":11,"question":"A digital frequency counter connected to a transmitter displays:","correct":"The frequency of the signal it is counting","wrong":["The SWR","The output power","The modulation depth"],"explain":"Counters measure frequency. Their accuracy depends on their reference oscillator."},
  {"id":"M-116","section":11,"question":"A frequency counter may give a wrong reading on an SSB signal because:","correct":"SSB has no steady carrier to count when there is no modulation, and the signal varies with speech","wrong":["SSB has too much carrier","Counters only read audio","SSB signals are always too strong"],"explain":"Counters need a steady signal. A modulated SSB signal gives a jumping or meaningless reading."},
  {"id":"M-117","section":11,"question":"A crystal calibrator's accuracy depends mainly on:","correct":"The accuracy and stability of its crystal","wrong":["The length of its antenna","The supply voltage only","The speaker size"],"explain":"A crystal calibrator is only as good as its crystal frequency."},
  {"id":"M-118","section":11,"question":"To measure transmitter output power without radiating, the transmitter should be connected through a power meter to a:","correct":"Dummy load","wrong":["Long-wire antenna","Speaker","Multimeter"],"explain":"A dummy load absorbs the RF as heat, so testing does not cause interference."},
  {"id":"M-119","section":11,"question":"An SWR meter is normally connected:","correct":"In the coax between the transmitter and the antenna (or ATU)","wrong":["Across the mains supply","In the microphone lead","Between the antenna and earth"],"explain":"It is inserted in the feedline to sample forward and reflected power."},
  {"id":"M-120","section":11,"question":"An SWR reading that suddenly rises well above normal suggests:","correct":"A fault in the feedline, connectors or antenna that should be investigated","wrong":["Improved band conditions","A better match","That more power should be used"],"explain":"Check for water in the coax, a loose connector or a damaged antenna before transmitting further."},
  {"id":"M-121","section":11,"question":"A multimeter set to the resistance range should never be connected to:","correct":"A circuit with power applied","wrong":["A resistor removed from a circuit","A length of wire","A fuse removed from equipment"],"explain":"Measuring resistance on a live circuit can damage the meter and gives false readings."},
  {"id":"M-122","section":11,"question":"A fuse can be checked for continuity using a multimeter on the:","correct":"Resistance (ohms) or continuity range","wrong":["AC voltage range while in a live circuit","Current range across the mains","Frequency range"],"explain":"A good fuse reads near 0 Ω. A blown fuse reads open circuit."},
  {"id":"M-123","section":11,"question":"When measuring current, the multimeter test lead is often moved to a separate socket because:","correct":"The current range uses a different internal path and fuse","wrong":["It improves voltage readings","It changes the meter to an SWR meter","It is required to measure resistance"],"explain":"Many meters have dedicated current sockets. Forgetting to move the lead back can blow the meter fuse."},
  {"id":"D-038","section":11,"question":"In the circuit shown, the ammeter (A) is connected:","correct":"In series, so the circuit current flows through it","wrong":["In parallel across the battery","In parallel across the resistor","Between the circuit and earth only"],"explain":"Ammeters are always placed in series with the circuit, as shown.","image":"assets/questions/cct-ohm.svg","imageAlt":"Battery, resistor R and ammeter in a single loop"},
  {"id":"D-067","section":11,"question":"In the circuit shown, the meter M is connected across the resistor. It is being used to measure:","correct":"Voltage across the resistor","wrong":["Current through the resistor","Resistance of the resistor while powered","Frequency"],"explain":"A meter connected in parallel (across) a component measures voltage. Current is measured in series.","image":"assets/questions/meter-parallel.svg","imageAlt":"Battery and resistor loop with meter M connected across the resistor"}
];
